  /* 분야별 AI 신문명 사업 기회 30 (부록 A) */
  var BOOK_OPPS = [{"no":1,"name":"소상공인 AI 매장 코치","lead":"매출, 날씨, 리뷰를 분석해 메뉴와 홍보 문구를 추천한다.","cost":"월 8만~20만 원. 유료 AI 구독 하나와 스프레드시트면 문을 연다. 첫 석 달은 장비를 사지 마라.","tools":"생성형 AI 챗봇 유료 요금제, 구글 스프레드시트, POS 매출 내보내기 파일, 기상청 단기예보 API, 네이버 플레이스 리뷰","first":"내가 이미 단골인 가게 세 곳. 한 달을 공짜로 해 주는 대신 매출 변화를 숫자로 받아 낸다. 그 숫자가 당신의 첫 제안서다."},{"no":2,"name":"시니어 AI 생활비서","lead":"복약, 일정, 가족 연락, 공공서비스 안내를 돕는다.","cost":"월 15만~40만 원. 태블릿 한 대와 통신비가 대부분이다. 개발보다 사람 만나는 데 돈이 더 든다.","tools":"음성 인식 AI, 큰 글씨 대응 태블릿, 복약 알림 앱, 지자체 복지포털 공개 데이터, 가족 알림용 메신저 봇","first":"요양보호사가 아니라 그 자녀다. 부모와 떨어져 사는 40~50대. 지역 맘카페와 아파트 입주민 단톡방에 첫 이용자가 있다."},{"no":3,"name":"AI 독서모임 플랫폼","lead":"책 요약이 아니라 질문 카드와 토론 흐름을 설계한다.","cost":"월 5만~12만 원. 이 목록에서 가장 싸게 시작할 수 있는 축에 든다.","tools":"생성형 AI 챗봇, 노션 또는 구글 문서, 온라인 모임 도구, 도서 DB(알라딘·교보 오픈API), 카카오톡 오픈채팅","first":"이미 운영 중인 독서모임 운영자. 새 모임을 만들지 말고, 모임을 굴리느라 지친 사람의 준비 시간을 대신 줄여 줘라."},{"no":4,"name":"지역 관광 AI 해설사","lead":"로컬 역사와 상점 정보를 다국어 스토리로 연결한다.","cost":"200만~600만 원. 콘텐츠 취재와 번역 검수에 대부분이 들어간다. 기술비는 오히려 적다.","tools":"다국어 생성형 AI, 지역 향토사 자료, QR 코드 생성기, 음성 합성 도구, 구글 지도 API","first":"지자체 관광과가 아니라 게스트하우스 사장이다. 예산 결재 라인이 짧다. 성수기 직전이 계약이 가장 빨리 되는 시기다."},{"no":5,"name":"중소기업 계약서 위험 점검 서비스","lead":"주요 조항, 누락, 협상 포인트를 설명한다.","cost":"300만~800만 원. 법률 자문 검수비를 반드시 예산에 넣어라. 여기서 아끼면 사업이 끝난다.","tools":"문서 분석형 AI, 표준계약서 데이터셋(공정위 공개), 변호사 감수 계약, 문서 암호화 저장소","first":"법무팀이 없는 직원 30인 이하 제조·용역 회사. 상공회의소 경영 세미나 뒤풀이 자리가 첫 미팅 장소가 된다."},{"no":6,"name":"학교용 AI 윤리 워크북","lead":"학생이 AI 답변을 검증하고 수정하는 과정을 평가한다.","cost":"100만~300만 원. 교사 자문료와 인쇄 시안비다. 워크북은 종이로 만들어야 팔린다.","tools":"생성형 AI, 워크북 편집 도구, 교육과정 성취기준 문서, 인쇄 POD, 교사 커뮤니티 계정","first":"정보 교사가 아니라 국어·사회 교사다. AI 답변을 검증하는 수업을 가장 절실하게 필요로 하는 쪽이다. 교육청 연수 강사로 먼저 들어가라."},{"no":7,"name":"AI 기반 1인 브랜드 편집실","lead":"글, 영상, 뉴스레터를 통합 기획하고 발행한다.","cost":"월 20만~50만 원. AI 구독 두세 개와 영상 편집 도구가 고정비의 전부다.","tools":"텍스트·이미지·영상 생성형 AI, 뉴스레터 발송 도구, 영상 편집 소프트웨어, 콘텐츠 캘린더, 브랜드 톤 가이드 문서","first":"팔로워 3천~3만 명 구간에서 정체된 1인 창작자. 유명인은 이미 팀이 있고, 초보는 돈이 없다. 그 사이의 사람이 지갑을 연다."},{"no":8,"name":"농업 병충해 이미지 진단 보조","lead":"현장 사진과 날씨 데이터를 바탕으로 대응을 안내한다.","cost":"500만~1,500만 원. 병징 이미지 데이터 확보가 가장 비싸다. 농업기술원 협업이 예산을 절반으로 줄인다.","tools":"이미지 인식 모델, 농촌진흥청 병해충 도감, 스마트폰 앱, 기상 데이터 API, 지역 농업기술센터 네트워크","first":"개별 농가가 아니라 작목반과 농협 지역조합이다. 한 번에 서른 명이 쓴다. 조합 총회 일정에 맞춰 데모를 준비하라."},{"no":9,"name":"돌봄기관 업무기록 자동 정리","lead":"반복 기록은 줄이고 돌봄 시간은 늘린다.","cost":"400만~1,000만 원. 개인정보 처리 설계와 보안 점검에 절반이 들어간다. 여기는 아끼면 안 되는 칸이다.","tools":"음성 인식 AI, 요양·장애인 시설 기록 서식, 개인정보 비식별화 도구, 폐쇄망 또는 온프레미스 환경, 사회복지사 자문","first":"시설장이 아니라 사무국장이다. 평가인증 서류를 밤새 만드는 사람이 결재를 밀어 준다. 인증 평가 3개월 전이 골든타임이다."},{"no":10,"name":"청년 진로 질문 코치","lead":"직업명보다 역량·성향·학습 경로를 중심으로 상담한다.","cost":"월 10만~25만 원. 상담 사례를 쌓는 시간이 진짜 비용이다. 돈보다 6개월이 든다.","tools":"생성형 AI, 직업정보 워크넷 데이터, 역량 진단 문항, 화상 상담 도구, 상담 기록 관리 시트","first":"대학 취업지원팀과 지자체 청년센터. 개인 상담료보다 기관 위탁 강의료가 먼저 들어온다. 학기 시작 두 달 전에 제안서를 넣어라."},{"no":11,"name":"지자체 민원 문장 표준화 도구","lead":"어려운 행정 문서를 시민 친화적으로 바꾼다.","cost":"200만~500만 원. 공공 문서 데이터 정제와 국어 전문가 감수비다.","tools":"생성형 AI, 국립국어원 쉬운 공공언어 지침, 행정용어 순화 자료, 문서 변환 도구, 웹 기반 편집기","first":"광역시가 아니라 인구 10만 이하 기초지자체다. 담당자가 한 명이라 결정이 빠르다. 민원 만족도 평가 시즌에 문이 열린다."},{"no":12,"name":"AI 안전성 사전 점검 컨설팅","lead":"출시 전 편향·개인정보·저작권·설명 가능성을 점검한다.","cost":"300만~900만 원. 대부분 당신의 학습비다. 자격이 아니라 사례가 자산이 된다.","tools":"EU AI Act 원문, 개인정보위 AI 가이드라인, 편향 테스트 도구, 모델 카드 서식, 체크리스트 템플릿","first":"AI 기능을 막 붙인 시리즈A 스타트업. 투자 실사에서 지적받은 다음 날 전화가 온다. VC 심사역과 먼저 친해져라."},{"no":13,"name":"AI 에너지 사용량 대시보드","lead":"조직의 AI 사용에 따른 전력과 탄소 영향을 추정한다.","cost":"400만~1,200만 원. 전력 환산 계수 검증과 대시보드 개발이 반반이다.","tools":"API 사용량 로그 수집기, IEA·환경부 배출계수, 데이터 시각화 도구, ESG 보고 서식, 클라우드 청구서 파싱","first":"ESG 공시 의무가 걸린 중견기업의 지속가능경영팀. 공시 마감 4개월 전에 예산이 풀린다."},{"no":14,"name":"전통시장 다국어 판매 보조","lead":"외국인 관광객에게 상품 설명과 결제 안내를 제공한다.","cost":"100만~400만 원. 태블릿 거치대와 다국어 검수비. 상인회 설득에 시간이 더 든다.","tools":"실시간 번역 AI, 태블릿 또는 키오스크, QR 결제 연동, 상품 사진 DB, 외국어 감수자","first":"개별 점포가 아니라 상인회장이다. 전통시장 활성화 지원사업 공고가 뜨는 3월과 9월에 맞춰 움직여라."},{"no":15,"name":"중장년 재교육 AI 튜터","lead":"실무 과제 중심으로 디지털 전환을 돕는다.","cost":"월 15만~40만 원. 강의 자료 제작이 초기 부담의 전부다.","tools":"생성형 AI, 학습관리 시스템, 실무 과제 뱅크, 화상 강의 도구, 수료 관리 시트","first":"개인 수강생이 아니라 기업 인사팀과 고용노동부 국민내일배움카드 훈련기관이다. 훈련과정 인정 신청이 먼저다."},{"no":16,"name":"출판 원고 반복·문체 점검 서비스","lead":"반복 문장과 반복적 표현을 편집자 관점으로 진단한다.","cost":"월 10만~30만 원. 이 책의 편집 과정 자체가 프로토타입이었다.","tools":"문체 분석 스크립트, 반복 표현 탐지기, 생성형 AI, DOCX 처리 라이브러리, 편집자 감수 체크리스트","first":"출판사가 아니라 자비출판·전자책 저자다. 원고를 다 쓰고 나서 불안해진 사람. 브런치와 크몽에 그 사람들이 모여 있다."},{"no":17,"name":"의료 설명문 쉬운 말 변환","lead":"환자가 이해하기 쉬운 언어로 검사 결과와 주의사항을 설명한다.","cost":"500만~1,500만 원. 의학 감수 계약이 비용을 좌우한다. 의료 광고 규제를 먼저 확인하라.","tools":"생성형 AI, 의학용어 표준 사전, 의료진 감수 계약, 검사 결과 서식, 환자 이해도 테스트","first":"대형병원이 아니라 검진센터와 동네 의원이다. 설명 시간이 곧 원가인 곳. 건강검진 성수기 직전에 제안하라."},{"no":18,"name":"공공기관 AI 사용 원칙 교육","lead":"직원이 안전하게 AI를 쓰는 기준과 사례를 훈련한다.","cost":"200만~600만 원. 교육 콘텐츠 제작과 사례집 구성비.","tools":"생성형 AI, 공공부문 AI 활용 지침, 사고 사례집, 온라인 교육 플랫폼, 이수 관리 시스템","first":"지자체 인재개발원과 공공기관 교육담당자. 연간 교육계획이 확정되는 11~12월에 접촉해야 다음 해 예산에 들어간다."},{"no":19,"name":"회의 후 실행 추적 에이전트","lead":"회의록을 할 일·담당자·기한·위험으로 변환한다.","cost":"300만~800만 원. 협업 도구 연동 개발이 대부분이다.","tools":"음성 인식 AI, 요약·구조화 AI, 협업 도구 API, 일정 관리 연동, 리스크 태깅 규칙","first":"회의가 많은 50~300인 규모 조직의 PMO나 기획팀. 회의록 담당이 정해져 있는 회사일수록 잘 팔린다."},{"no":20,"name":"창작자 음성·초상권 관리 서비스","lead":"AI 복제 사용 동의와 보상 이력을 관리한다.","cost":"400만~1,200만 원. 계약 서식 설계와 법률 검토에서 승부가 난다.","tools":"음성·이미지 지문 대조 기술, 저작인접권 표준계약서, 사용 이력 관리 DB, 전자서명, 엔터 법무 자문","first":"톱스타가 아니라 성우, 세션 연주자, 유튜브 내레이터다. 이미 복제 피해를 겪었지만 대응할 방법이 없는 사람들이다."},{"no":21,"name":"로컬 축제 수요 예측 도구","lead":"방문객 흐름과 상권 효과를 예측한다.","cost":"300만~900만 원. 유동인구·카드매출 데이터 구매비가 변수다.","tools":"통신사·카드사 상권 데이터, 기상 데이터, 예측 모델링 도구, 시각화 대시보드, 축제 운영 이력 자료","first":"축제 대행사와 문화재단이다. 정산 보고서에 넣을 근거가 필요한 쪽이 먼저 산다. 축제 종료 직후가 영업 적기다."},{"no":22,"name":"개인 지식 금고","lead":"민감정보를 보호하면서 자신의 문서와 메모를 검색한다.","cost":"200만~700만 원. 로컬 실행 환경 구성이 비용의 중심이다.","tools":"온디바이스 소형 언어모델, 벡터 검색 엔진, 문서 파서, 암호화 저장소, 데스크톱 앱 프레임워크","first":"변호사, 세무사, 연구자처럼 자료를 밖으로 못 내보내는 1인 전문가. 보안 각서가 있는 직업군을 먼저 노려라."},{"no":23,"name":"장애인 접근성 콘텐츠 변환","lead":"영상·문서·안내문을 여러 접근 형식으로 바꾼다.","cost":"300만~800만 원. 접근성 표준 검증과 당사자 테스트비다.","tools":"음성 합성·자막 생성 AI, 이미지 대체텍스트 생성, 웹 접근성 지침(KWCAG), 쉬운 말 변환기, 당사자 모니터단","first":"공공기관 홍보실과 장애인복지관이다. 접근성은 권고가 아니라 의무인 영역이 이미 넓다. 조달 등록을 서둘러라."},{"no":24,"name":"AI 면접 공정성 감사","lead":"질문 편향과 평가 기준을 점검한다.","cost":"200만~600만 원. 감사 방법론 정립과 판례 조사에 든다.","tools":"편향 측정 도구, 채용 관련 법령·판례, 면접 질문 데이터셋, 통계 분석 도구, 노무사 자문","first":"AI 면접을 도입했다가 지원자 항의를 받은 기업의 인사팀. 그리고 공공기관 채용 감사 대응 부서다."},{"no":25,"name":"프랜차이즈 운영 AI 매뉴얼","lead":"지점별 문제를 빠르게 표준 지식으로 전환한다.","cost":"400만~1,000만 원. 지점 사례 수집과 지식 구조화가 대부분이다.","tools":"생성형 AI, 지식 검색 엔진, 슈퍼바이저 리포트 서식, 모바일 앱, 지점 문의 로그","first":"가맹점 50~300개 구간의 프랜차이즈 본사 운영팀. 슈퍼바이저 한 명이 감당 못 하기 시작하는 규모가 정확히 여기다."},{"no":26,"name":"ESG·AI 통합 리포트 자동화","lead":"환경·사회·거버넌스와 AI 리스크를 함께 보고한다.","cost":"500만~1,500만 원. 공시 기준 대응과 검증 로직 개발비다.","tools":"ESG 공시 기준(ISSB·KSSB), AI 리스크 분류 체계, 데이터 수집 자동화, 보고서 생성 AI, 회계법인 검증 파트너","first":"지속가능경영보고서를 처음 내는 중견기업. 대기업은 이미 컨설팅사가 붙어 있다. 그 아래 층을 공략하라."},{"no":27,"name":"가족 AI 사용 계약서","lead":"가정에서 데이터·학습·콘텐츠 사용 원칙을 세운다.","cost":"50만~200만 원. 콘텐츠와 워크숍 설계가 전부다. 개발이 거의 필요 없다.","tools":"가족 대화 워크북 서식, 연령별 AI 사용 가이드, 인쇄 POD, 온라인 강의 도구, 학부모 커뮤니티","first":"초등 고학년 자녀를 둔 학부모다. 학교 학부모회 특강과 도서관 강좌가 첫 무대다. 강의가 곧 상품 판매다."},{"no":28,"name":"교회·비영리단체 AI 행정 도우미","lead":"공지·상담 기록·봉사매칭을 안전하게 돕는다.","cost":"100만~400만 원. 개인정보 처리 설계와 소식지 서식 제작.","tools":"생성형 AI, 교인·회원 관리 시스템, 상담 기록 비식별화 규칙, 봉사 매칭 알고리즘, 소식지 자동 편집","first":"담임목사나 대표가 아니라 사무간사다. 주보와 소식지를 매주 만드는 사람이 가장 먼저 감동한다."},{"no":29,"name":"도시 재난대응 정보 요약 시스템","lead":"재난 상황 정보를 시민 언어로 빠르게 전달한다.","cost":"600만~2,000만 원. 실시간 데이터 연계와 다국어 검수가 크다.","tools":"재난문자·기상특보 API, 요약 생성 AI, 다국어·쉬운 말 변환, 지도 시각화, 지자체 재난안전과 협업","first":"지자체 재난안전과와 아파트 관리사무소 연합회다. 재난이 한 번 지나간 지역의 예산이 가장 빠르게 움직인다."},{"no":30,"name":"AI 시대 베스트셀러 기획 코치","lead":"독자페인포인트·목차·사례·실행 미션을 통합 설계한다.","cost":"월 10만~30만 원. 이 책 한 권이 곧 포트폴리오가 된다.","tools":"생성형 AI, 원고 구조 분석 도구, 서점 판매 데이터, 독자 인터뷰 스크립트, 출판 기획서 서식","first":"강의는 하는데 책이 없는 전문가다. 이미 콘텐츠는 넘치고 구조만 없는 사람. 협회 세미나 연사 명단이 곧 고객 명단이다."}];

  /* 책 전체 인용문 */
  var BOOK_QUOTES = ["파도는 이름을 기다려 주지 않는다. 이름을 먼저 지은 쪽이 먼저 배를 띄운다.","파도를 검색하는 사람은 늦고, 파도를 읽는 사람은 빠르며, 파도를 지휘하는 사람은 새 문명의 첫 문장을 쓴다.","현재 위치를 모르는 사람에게는 어떤 지도도 백지다.","같은 파도 앞에서 셋의 자리를 가른 것은 재능이 아니라, 아침 십 분을 어디에 썼느냐였다.","한 장, 한 문장, 한 가지. 문명은 늘 그 정도의 크기로 바뀌기 시작했다.","파도는 모두에게 온다. 갈리는 것은 파도가 아니라, 젖기 전에 무엇을 물었느냐다.","지금이 ‘처음으로 도구가 도구 사용자가 된’ 첫 순간이다.","제3의 물결은 정보의 흐름을 바꿨다. 제5의 물결은 판단의 주체를 바꾼다. 후자가 더 크다.","제3의 물결이 정보의 흐름을 바꿨다면, 제5의 물결은 판단의 주체를 바꾼다.","인류의 마지막 문명이 될 것인가, 아니면 완전히 새로운 시작이 될 것인가. 그 거대한 주사위는 지금, 우리가 관통하고 있는 이 5년의 시간 속에 던져져 있다.","점수보다 중요한 건 변화의 곡선이다. 6주 후 다시 측정해 보라. 당신이 변하고 있는지, 멈춰 있는지가 보일 것이다.","답은 0.1초의 일이다. 질문은 평생의 일이다.","당신의 일자리가 사라지는 것이 아니다. 당신의 일이 ‘무엇으로 구성되어 있는가’가 바뀌는 것이다. 그 비율을 다시 그릴 수 있는 사람만이 다음 10년에 살아남는다.","당신의 일은 사라지지 않는다. 그 일의 구성이 바뀐다.","토지에는 등기부가 있다. 데이터에는 아직 없다. Data Act는 데이터에 ‘등기부’를 도입한 첫 번째 시도다. 다음 10년은 데이터의 ‘소유’가 아니라 ‘이용 권리의 흐름’으로 정의될 것이다.","데이터는 ‘소유’의 자산이 아니라 ‘이용 권리의 흐름’의 자산이다.","당신의 클릭은 무료가 아니다. AI 시대의 ‘데이터 세금’과 ‘데이터 소득’을 지금, 선언하자.","기술의 진보가 만드는 과실은 누구의 것인가.","나의 일상이 AI를 키웠다면, 그 결실의 일부도 나의 일상으로 돌아와야 한다.","알고리즘은 자기가 누구 편인지 말하지 않는다. 그래서 우리는 결정의 이유를 끝까지 물어야 한다. 그것이 시민의 첫 번째 의무다.","알고리즘은 누구 편인지 스스로 밝히지 않는다. 그래서 시민이 물어야 한다.","기본소득은 정답이 아니라 ‘실험 가설’이다. AI 시대의 정책은 ‘이념’이 아니라 ‘증거’로 설계되어야 한다. 우리는 그 증거를 모으는 중이다.","정답이라 우기는 순간 정책은 늙는다. 기본소득은 아직 젊은 가설이다.","AI 한 번 묻는 데 전기 한 컵이 든다. 모두가 하루에 백 번 묻기 시작했다. 우리는 이 ‘작은 컵의 합계’를 언제까지 모른 척할 수 있을까.","리터러시는 시험 점수가 아니다. 6개월 후 다시 측정해 보라. 점수가 올라간다면, 당신은 시대를 따라가고 있다.","AI를 잘 쓰는 사람이 아니라, AI에게 좋은 질문을 하는 사람이 시대를 가져간다.","에이전트는 비서가 아니라 동료다. 그래서 진짜 능력은, 일을 시킬 줄 아는 능력이다.","세 트랙을 모두 동시에 시작하지 마라. 한 트랙으로 30일을 채우고, 그 흐름이 자동화될 때 다음 트랙을 더하라. 1인 브랜드는 ‘체력’이 아니라 ‘레이어링’의 예술이다.","도구가 평준화될수록, 값이 매겨지는 것은 도구가 아니라 그 도구를 쥔 사람의 관점이다.","본문은 ‘어떻게 생각하는가’의 학교다. 부록은 ‘무엇을 시도할 것인가’의 작업장이다. 두 곳을 오가는 자가 다음 1인 유니콘이 된다.","신사업은 ‘큰 시장’에서 시작되지 않는다. ‘구체적인 한 사람의 불편’에서 시작된다.","AI를 소유한 사람이 아니라, AI 조직을 지휘할 줄 아는 사람이 다음 문명의 부를 가져간다.","로드맵의 첫 칸은 ‘이 분기 안에 달성 가능한 작은 승리’여야 한다.","제도가 너무 느리면 시민이 다친다. 그러나 제도가 너무 빠르면 혁신이 죽는다. 좋은 사회는 6개의 기어를 다 가진 자전거다.","좋은 사회는 기술과 제도의 속도가 같지 않다는 사실을 두려워하지 않는다.","AI 패권은 기술의 패권이 아니라, ‘인재 + 데이터 + 에너지 + 신뢰’의 합산이다.","중소기업의 무기는 ‘속도’와 ‘맥락’이다. AI는 그 두 무기를 나란히 두 배로 키운다.","기술이 따뜻해질 수 있을까. 우리는 그 답을 매일 작은 거실에서 확인하고 있는데, 화면 너머로 건너오는 ‘안녕하세요’ 한마디가, 어떤 노인에게는 그날 들은 유일한 사람의 목소리일 수도 있으니까.","돌봄 AI의 본질은 ‘대체’가 아니라 ‘부분 보조’다. 사람의 시간을, 다시 사람에게 돌려주는 일이다.","교육과 출판의 미래는 ‘큐레이션 + 신뢰’다. 정보는 흔하고, 신뢰는 귀하다.","로컬의 미래는 ‘거리’가 아니라 ‘이야기’로 결정된다. AI는 그 이야기를 세계로 실어 나르는 배다.","가장 큰 변화는 언제나 가장 가까운 방에서 먼저 일어난다.","내용을 줄이고, 깊이를 늘리고, 디지털·AI 소양을 모든 교과에 녹인다.","학교의 미래는 ‘무엇을 가르치는가’가 아니다. ‘어떤 질문을 함께 던지는가’에 있다.","1인 유니콘은 외로움이 아니라 ‘레버리지’의 다른 이름이다. 혼자라는 사실이 약점이 아니라 강점이 되는 시대 — 그것이 AI 시대 ‘작은 거인’의 진짜 풍경이다.","영향력의 단위가 ‘사람 수’에서 ‘시스템 수’로 바뀌었다.","자녀에게 ‘AI를 쓰지 마라’ 대신 ‘AI와 어떻게 살아갈지 함께 배워 보자’고 말할 수 있는 부모가, 가장 좋은 부모다.","부모의 가장 좋은 유산은 ‘답’이 아니라 ‘함께 묻는 식탁’이다.","카메라는 잘못이 없다. 문제는 ‘누가, 어떤 조건에서, 무엇을 볼 권한이 있는가’이다. 그 답을 시민이 정하지 못하면, 권력이 대신 정한다.","감시와 보호를 가르는 것은 기술이 아니라, 그 기술을 지켜보는 시민의 눈이다.","복제되는 것은 언제나 솜씨이고, 복제되지 않는 것은 다음에 무엇을 할지 정하는 손이다.","창의성은 죽지 않는다. 다만 그 자리가 바뀐다 — 손에서 시선으로.","K-팝은 AI 시대의 정체성 실험을 가장 화려한 무대 위에서 한다. 그들이 ‘나의 복제본과 어떻게 공존할 것인가’의 답을 찾을 때, 우리 모두에게 적용될 답이 만들어진다.","복제본이 무대에 오른다. 그러나 무대 뒤의 ‘진짜’가, 더 비싸진다.","알고리즘을 가진 자가 권력을 가진다. 그러나 시민의 눈을 가진 자가, 그 권력을 견제한다.","오래된 물음은 낡아서가 아니라 아직 답이 없어서 되돌아온다.","지식이 폭발하는 시대일수록, 지혜의 정원사가 귀해진다.","좋은 삶은 정의되지 않는다. 매일 다시 선택되는 것이다.","상상력은 지식보다 앞서지만, 책임은 상상력보다 더 앞서야 한다.","안전벨트는 사고가 난 뒤에 발견되는 발명이 아니다. 사고가 나기 전에 채워 두는 약속이다. AI Act는 인류가 처음으로 시도하는, 바로 그 약속이다.","채우는 데 삼 초, 안 채운 대가는 평생. 규칙이란 원래 그런 계산이다.","측정할 수 있다고 해서 모든 것이 측정의 대상이 되어야 하는 것은 아니다. 그러나 측정되지 않는다는 이유로 ‘없는 것’ 취급된 인간의 능력들이 너무 많았다. 공감 자본이라는 새 단어는, 잃어가던 가치에 새 좌석을 마련해 주는 일이다.","인간성은 측정되지 않는 것이 아니라, 측정되지 않는다는 이유로 잊혔던 것이다.","인간 선언은 외워서 읽는 책의 마지막 페이지가 아니다. 당신이 직접 쓰는 자기 자신과의 계약서다. 이 한 장을 책상 앞에 붙여두라.","이 일곱 가지 약속은 자물쇠가 아니라 나침반이다.","방향은 예측이 아니라 선택이다. 선택은 좌표를 가진 사람의 권리다.","도구형 AI → 생성형 AI → 자율형 AI → 공진화형 AI → 문명형 AI.","누구의 AI가 사회의 운영체제가 되는가?」 「AI가 내린 결정에 누가 책임지는가?」 「AI 인프라에 접근하지 못하는 사람은 어떻게 보호받는가?","우리는 AI를 어디까지 쓰고 있나요?","귀사는 지금 ‘생성형 AI 활용 초기’ 단계에 있습니다. 다음은 ‘자율형 에이전트 도입’ 단계입니다. 그다음은 ‘부서 간 공진화 단계’이고요. 한 단계씩 가야 합니다.","도구가 처음으로 문명이 된다. 그 자리에 인간이 함께 앉아 있어야, 문명은 인간의 것이다.","얘야, 요즘 너 회사에서 뭐 하니. 예전에는 사장이 시키는 일을 했지. 요즘은 뭘 하니?","엄마, 요즘 저는 AI랑 이야기해요. AI한테 일을 시키고, AI가 잘했는지 봐주고요. 가끔은 AI가 무서워서 한 번 더 묻기도 하고요.","그러면 너는 사람이 사람한테 일 시키는 거 말고, 사람이 기계한테 일 시키고 사람한테 결정을 받는 사람이구나.","도구가 바뀌면 사람이 바뀐다. 다만 어느 방향으로 바뀔지는, 여전히 사람이 고른다.","미래는 오는 게 아니라 만들어진다. 그 만드는 자리에 우리도 앉아 있다. 그 자리를 비우면, 다른 누군가가 우리 대신 앉아 우리의 미래를 결정한다.","비워 둔 의자에는 반드시 누군가 앉는다. 그 누군가가 당신이 아닐 뿐이다.","파도 이후의 인간은, 파도를 사랑할 줄 아는 인간이다.","30선은 ‘이것을 시작하라’는 명령이 아니다. ‘당신이 시작할 수 있는 30개의 가능성’의 진열장이다. 그중 한 칸을 손에 들어 책상에 두는 순간, 부록은 사업계획서로 바뀐다.","답을 멈추는 자가, 답을 얻는다.","프롬프트는 명령이 아니라 대화다.","오늘 한 가지 업무를 AI에게 맡기고, 그 시간을 사람에게 돌려주라.","의심하지 않는 답은, 내 답이 아니다.","반복되는 일을 자동화하라. 처음 하는 일에 시간을 쓰라.","6주 후의 너는, 지금의 너에게 한 가지를 물을 것이다 — ‘왜 더 일찍 시작하지 않았어?’"];

  /* 미리보기 본문 — 58쪽 */
  var BOOK_PREVIEW = [{"part":"여는 글","title":"파도에 이름이 붙기 전에","sid":"s01","blocks":[{"k":"p","t":"지금 이 순간에도, 이름이 아직 없는 무언가가 조용히 답을 만들어 내고 있다. 어떤 도시에서는 밤이고 어떤 도시에서는 벌써 점심이다. 아무도 그것을 보지 않는다. 그런데도 답은 쌓인다."},{"k":"p","t":"나는 이 장면을 오래 들여다봤다."},{"k":"p","t":"인류가 겪은 앞선 네 번의 파도에는 늘 이름이 늦게 붙었다. 밭을 갈던 사람은 자기가 농업혁명 한가운데 서 있다고 생각하지 않았고, 방직기 옆에 선 소년도 산업혁명이라는 말을 들어 본 적이 없었다. 이름은 언제나 파도가 지나간 뒤에 붙는다. 물이 빠지고 젖은 모래가 드러난 다음에야, 사람들은 그것을 뭐라고 불러야 할지 합의한다."},{"k":"p","t":"이번에는 달랐으면 한다."},{"k":"p","t":"지금 문턱을 넘고 있는 다섯 번째 물결에는, 지나가기 전에 이름을 붙여 두고 싶다. 이름이 없는 것은 대비할 수 없기 때문이다."},{"k":"p","t":"그래서 이 책은 낱말부터 시작한다. AI 자율화혁명 — 기계가 시키는 대로 하는 단계를 지나 목적을 받아 스스로 경로를 짜는 국면. AI 디렉터 — 답을 만드는 사람이 아니라 답의 방향을 정하고 책임을 지는 사람. A·H·AH — 인공지능과 인간이 부딪히다 결국 감탄에 도달하는 자리. AI 공진화 사피엔스 — 도구에 밀려나는 대신 도구와 함께 다시 진화하기로 한 종."},{"k":"p","t":"낯설 것이다. 사전에 없는 말들이니까."},{"k":"p","t":"하지만 새 문명은 늘 새 낱말을 데리고 오는데, 전기가 오기 전에는 정전이라는 말이 없었고, 인터넷이 오기 전에는 접속이라는 말이 지금의 뜻을 갖지 않았다. 먼저 이름을 아는 쪽이 먼저 값을 매긴다. 그것이 모든 문명 전환기의 조용한 규칙이었다. 전기라는 말을 먼저 익힌 마을이 밤을 먼저 늘렸고 접속이라는 말을 먼저 쥔 세대가 시장을 먼저 가져갔듯, 낱말 하나를 늦게 배운 대가는 언제나 한참 뒤에 청구서로 도착했다."}],"no":1},{"part":"여는 글","title":"파도에 이름이 붙기 전에","sid":"s01","blocks":[{"k":"p","t":"이 책에는 그런 낱말이 쉰 개 실려 있다. 서른일곱 개의 질문과 서른 개의 기회도 함께 있다. 그러나 진짜로 남기고 싶은 것은 낱말도 목록도 아니다."},{"k":"p","t":"당신이 다음 문장을 읽고 나서, 오늘 저녁에 무엇을 다르게 할 것인가. 그 한 칸이다."},{"k":"p","t":"나는 이 책에서 예언을 하지 않는다. 예언은 빗나가면 부끄럽고 맞아도 쓸모가 없다. 대신 좌표를 찍는다. 지금 당신이 서 있는 자리, 물이 차오르는 방향, 발을 옮길 수 있는 칸. 항해에 필요한 것은 미래의 사진이 아니라 한 장의 해도(海圖)다. 예언은 맞으면 잠시 신기하고 틀리면 곧 잊히지만 좌표는 그렇게 소비되지 않는데, 물이 어디까지 차올랐는지 정확히 알아야 오늘 저녁 어느 쪽 발부터 옮길지 스스로 정할 수 있기 때문이다."},{"k":"p","t":"그러니 이 책은 처음부터 끝까지 읽지 않아도 좋다."},{"k":"p","t":"목차를 훑다가 심장이 한 번 뛰는 곳에서 멈추면 된다. 거기가 당신의 파도다. 나머지는 그 파도를 건넌 뒤에 읽어도 늦지 않다."},{"k":"p","t":"파도는 누구에게나 공평하게 온다. 갈리는 것은 파도가 아니라, 그 앞에서 무엇을 물었느냐다. 같은 새벽에 같은 물이 밀려들어도 어떤 사람은 창문을 닫으러 일어나고 어떤 사람은 해도를 펴러 일어나는데, 그 사소한 기척의 차이가 십 년 뒤에 두 사람이 서 있을 자리를 조용히 갈라놓는다."},{"k":"quote","t":"「파도는 이름을 기다려 주지 않는다. 이름을 먼저 지은 쪽이 먼저 배를 띄운다.」"}],"no":2},{"part":"여는 물결","title":"새벽 세 시, 파도가 먼저 도착했다","sid":"s02","blocks":[{"k":"h","t":"여는 물결: 새벽 세 시,\n파도가 먼저 도착했다"},{"k":"p","t":"새벽 세 시. 도시가 가장 조용해지는 시각에, 세상은 가장 크게 바뀐다."},{"k":"p","t":"당신이 잠든 사이에도 어느 병원의 AI는 엑스레이 삼천 장을 읽었다. 어느 번역 엔진은 여섯 개의 언어로 계약서를 옮겼고, 어느 물류 창고에서는 기계 팔이 내일 아침 당신의 문 앞에 놓일 상자를 골라냈다. 소리는 없었다. 원래 큰 파도는 소리보다 먼저 온다."},{"k":"p","t":"두 사람이 같은 파도를 만났다. 한 사람은 젖을 걱정부터 했고, 한 사람은 바람의 방향을 쟀다. 십 년 뒤 두 사람의 자리를 갈라놓은 것은 파도가 아니라 그 순간의 시선이었다. 문명의 전환기마다 되풀이된 오래된 장면이다. 활자가 처음 찍히던 밤에도, 증기기관이 처음 울리던 아침에도, 누군가는 문을 걸어 잠갔고 누군가는 배를 만들었다. 그리고 역사는 언제나 배를 만든 사람의 이름을 먼저 적었다. 활자가 처음 찍히던 밤에 문을 걸어 잠근 사람도 게으르지는 않았고 오히려 누구보다 부지런히 자기 창고를 지켰지만, 그 부지런함이 향한 곳이 안쪽이었다는 사실만은 끝내 달라지지 않았다."},{"k":"p","t":"이 책은 그 파도에 이름을 붙인다. 제5의 물결. 농업은 문명을 세웠고, 산업은 문명을 키웠고, 정보는 문명을 연결했고, 플랫폼은 문명을 하나의 시장으로 묶었는데, 다섯 번째 물결이 지금 문턱을 넘는다. 이번 파도는 도구에게 생각을 가르쳤다. 도구가 생각을 시작하면, 질문은 인간에게 되돌아온다. 그렇다면 당신은, 무엇을 생각할 것인가."},{"k":"p","t":"파도는 국경을 가리지 않는다. 서울의 새벽과 헬싱키의 정오와 나이로비의 저녁이 같은 물결 위에서 출렁인다. 농부는 하늘을 읽어 파종을 정했고 상인은 바람을 읽어 항로를 정했듯, 이제 우리는 알고리즘의 결을 읽어 삶의 항로를 정하는데, 도구는 바뀌었어도 문법은 그대로다. 결을 읽는 자가 먼저 도착한다."}],"no":3},{"part":"여는 물결","title":"새벽 세 시, 파도가 먼저 도착했다","sid":"s02","blocks":[{"k":"p","t":"여기서 잠깐, 불편한 계산을 하나 해 보자. 오늘 하루 당신은 몇 번 답을 얻었고, 몇 번 질문을 만들었는가. 대부분은 전자가 압도적으로 많지만 값이 붙는 쪽은 후자인데, 답이 이미 공짜가 된 탓이고, 공짜가 된 것 옆에는 늘 새로 비싸지는 것이 생기기 때문이다. 이번에 비싸진 것은 판단이다."},{"k":"p","t":"그 사실을 먼저 알아챈 사람들이 있다. 회사를 그만두지도, 대단한 결심을 하지도 않았다. 다만 아침마다 십 분씩 자기 일에 질문을 적었다. 일 년이 지나자 그 십 분이 오백 시간이 되었고, 오백 시간은 이력서 한 줄로는 설명되지 않는 자리를 만들었다. 반대편에는 똑같이 성실했지만 아무 질문도 적지 않은 사람이 있었다. 두 사람 사이에 벌어진 것을 이 책은 조용한 격차라고 부른다. 뉴스에 나오지 않아서 더 무서운 격차다. 그 십 분은 달력에 표시되지도 않고 통장에 찍히지도 않지만, 어느 봄날 회의실에서 누군가 던진 질문 하나로 조용히 모습을 드러내며 그동안 쌓인 시간의 두께를 한꺼번에 증명한다."},{"k":"p","t":"이 책은 그 격차의 이름들을 하나씩 붙여 나갈 텐데, 판단에 값이 붙는 현상을 판단 프리미엄이라 부르고, 같은 도구를 쥐고도 결과가 갈리는 선을 프롬프트 계급이라 부른다. 기술이 도착한 날과 규칙이 도착하는 날 사이의 삼 년을 알고리즘 시차라 부르고, 기계가 구십구 미터를 옮겨도 사람이 걸어야 하는 구간을 마지막 1미터라 부른다. 이름을 붙이는 일은 사소해 보이지만 사소하지 않다. 이름이 없는 것은 대비할 수 없다."}],"no":4},{"part":"여는 물결","title":"새벽 세 시, 파도가 먼저 도착했다","sid":"s02","blocks":[{"k":"p","t":"앞으로 페이지마다 낯선 낱말들이 마중 나올 것이다. 기술이 스스로 판단하고 실행하는 단계로 올라서는 대전환, AI 자율화혁명. 답을 받아 적는 사람이 아니라 방향을 지휘하는 사람, AI 디렉터. AI가 잘하는 일(A)과 인간만이 할 수 있는 일(H), 그리고 둘이 만났을 때 폭발하는 일(AH)을 가르는 세 칸의 지도, A·H·AH. 도구와 함께 다음 단계로 건너가는 인간, AI 공진화 사피엔스. 낯설어도 괜찮다. 새 문명은 언제나 새 낱말과 함께 도착했다."},{"k":"p","t":"두려움은 자연스럽다. 다만 기억해 두자. 파도 앞에서 젖는 사람과 항해하는 사람의 차이는 수영 실력이 아니라, 손에 지도가 있느냐였다. 이 책은 그 지도다. 예언서가 아니라 해도(海圖)다. 페이지를 넘길 때마다 당신의 일, 당신의 아이, 당신의 사업, 당신의 도시가 파도 위 어디쯤에 있는지 좌표가 하나씩 찍힐 것이다."},{"k":"p","t":"마지막으로 한 문장을 미리 건넨다. 책장을 덮은 뒤에도 이 문장만은 곁에 남기를 바라며."},{"k":"quote","t":"「파도를 검색하는 사람은 늦고, 파도를 읽는 사람은 빠르며, 파도를 지휘하는 사람은 새 문명의 첫 문장을 쓴다.」"},{"k":"p","t":"그러니 본문을 서두르지 말자. 먼저 딱 일 분. 바로 다음 장에 짧은 진단표를 두었다. 지금 당신이 파도의 어디쯤 서 있는지 확인하는 데는 연필 한 자루면 충분하다. 모든 항해는 현재 위치를 찍는 데서 시작된다."}],"no":5},{"part":"여는 물결","title":"파도에는 이미 이름이 붙어 있다","sid":"s03","blocks":[{"k":"p","t":"말이 먼저 도착하고 사건이 뒤따르는 시절이 있다. 지금이 그렇다."},{"k":"p","t":"몇 해 전만 해도 낯설던 낱말들이 요즘은 회의실 한복판에서 아무렇지 않게 오간다. 그런데 이상한 일이 벌어진다. 그 말을 쓰는 사람과 못 알아듣는 사람이 같은 방에 앉아 있는데, 회의가 끝나면 두 사람의 일은 완전히 다른 방향으로 굴러간다. 능력의 차이가 아니었다. 어휘의 차이였다."},{"k":"p","t":"문명이 바뀔 때마다 되풀이된 일이다. 증기기관이 도착했을 때 사람들은 ‘공장’이라는 말을 새로 배웠고, 전기가 왔을 때는 ‘회로’를, 인터넷이 왔을 때는 ‘접속’을 배웠다. 먼저 배운 사람이 먼저 값을 매겼다. 낱말은 지식이 아니라 좌표였다. 어디에 서 있는지 알아야 어디로 갈지 정할 수 있으니까."},{"k":"p","t":"이번 파도가 데려온 말들도 다르지 않다. 넷만 미리 꺼내 둔다. 뒤에서 하나씩 다시 만날 것이다."},{"k":"p","t":"첫째, AI 자율화혁명. 기계가 시키는 대로 빨리 하는 단계에서, 목적만 들으면 절차를 스스로 짜는 단계로 넘어가는 대전환이다. 자동화와 자율화 사이에는 한 글자 차이가 아니라 문명 하나가 들어 있다."},{"k":"p","t":"둘째, AI 디렉터. 촬영장에서 카메라를 드는 사람과 “컷”을 외치는 사람이 다르듯, 앞으로의 일터는 답을 받아 적는 사람과 방향을 정하고 책임에 서명하는 사람으로 갈린다. 감독은 배우보다 연기를 잘하지 않는다. 다만 어느 장면을 남길지 안다."},{"k":"p","t":"셋째, A·H·AH. 내 일을 세 칸으로 갈라 보는 지도다. AI가 더 잘하는 일(A), 사람만이 할 수 있는 일(H), 그리고 둘이 만났을 때 혼자서는 닿지 못했던 높이에 닿는 일(AH). 대부분은 A 칸을 들여다보며 불안해하지만, 값이 붙는 자리는 늘 세 번째 칸이었다."}],"no":6},{"part":"여는 물결","title":"파도에는 이미 이름이 붙어 있다","sid":"s03","blocks":[{"k":"p","t":"넷째, AI 공진화 사피엔스. 진화는 한쪽만 변하는 일이 아니다. 꽃과 벌은 서로를 바꾸며 함께 왔다. AI는 인간이 남긴 문장으로 자라고, 인간은 AI와 주고받으며 생각하는 방식이 바뀐다. 서로가 서로의 환경이 된 종(種). 그게 지금의 우리다."},{"k":"p","t":"철학자들은 오래전부터 도구가 인간을 바꾼다고 말해 왔다. 망치를 쥐면 세상이 못으로 보인다는 오래된 농담이 그것이다. 이번에는 조금 다르다. 이 도구는 우리가 무엇을 못으로 볼지까지 제안한다. 그러니 물어야 할 것은 “이 도구로 무엇을 할까”가 아니라 “이 도구를 쥔 나는 어떤 사람이 되는가”다."},{"k":"p","t":"미래학은 예언이 아니다. 이미 도착했지만 아직 고르게 퍼지지 않은 것들을 먼저 알아보는 기술이다. 이 책이 하려는 일도 그것뿐이다. 앞으로 서른일곱 개의 장을 지나는 동안, 당신 손에는 낯선 낱말 쉰 개와 사업 기회 서른 개, 그리고 여섯 주짜리 실행표 한 장이 남는다."},{"k":"p","t":"다만 순서가 있다. 지도를 펴기 전에 현재 위치부터 찍어야 한다. 낯선 도시에서 길을 잃은 사람이 지도부터 펼치지 않고 가장 가까운 건물의 이름을 먼저 확인하듯, 다음 장의 진단표도 답을 주기 전에 당신이 지금 어디쯤 서 있는지부터 묻는다."}],"no":7},{"part":"1분 진단","title":"당신은 파도의 어디쯤 서 있는가","sid":"s04","blocks":[{"k":"p","t":"1분 생존 진단:\n당신은 파도의 어디쯤 서 있는가"},{"k":"h","t":"AI 시대 개인 생존력 자가 진단표: 당신은 지배할 것인가, 지배당할 것인가"},{"k":"p","t":"아래 질문에 빠르게 표시해 보라. 오래 생각하지 말고 현재의 나를 기준으로 답하면 된다. 그렇다는 1점, 아직 아니다는 0점이다. 점수는 거들 뿐이다. 어느 질문 앞에서 손이 멈췄는지, 그것만 확인하면 된다. 진단표 앞에서 사람들이 가장 오래 멈추는 칸은 도무지 모르는 항목이 아니라 이미 알면서도 올해 내내 뒤로 미뤄 둔 항목이었고, 손끝이 잠시 머문 그 한 줄이 점수 합계보다 훨씬 정직한 자기 보고서가 된다."},{"k":"diagtable","t":""},{"k":"h","t":"점수 합계: ______점"},{"k":"h","t":"진단 결과"},{"k":"p","t":"8~10점: AI 지휘자형이다. 이미 도구를 쓰는 단계를 넘어 판단의 주도권을 고민하고 있다. 10장 「AI 리터러시」, 13장 「AI 신문명 사업 기회」, 14장 「기업과 도시를 위한 AI 전환 로드맵」, 31장 「AI 윤리와 문명의 안전벨트」를 먼저 읽으면 다음 실행점이 선명해진다."}],"no":8},{"part":"1분 진단","title":"당신은 파도의 어디쯤 서 있는가","sid":"s04","blocks":[{"k":"p","t":"4~7점: AI 전환기형이다. 불안과 가능성이 함께 있는 자리다. 1장 「왜 지금 AI 문명인가」, 4장 「질문하는 인간의 귀환」, 5장 「일의 재설계: 내 일자리는 사라지는가, 다시 짜이는가」, 6장 「데이터는 새로운 토지인가」, 10장 「AI 리터러시」를 따라가며 내 일의 지도를 먼저 그리는 편이 좋다."},{"k":"p","t":"0~3점: AI 경고등형이다. 늦었다는 뜻이 아니다. 가장 빨리 바뀔 수 있는 출발점에 섰다는 뜻이다. 프롤로그와 1장 「왜 지금 AI 문명인가」, 2장 「제5의 물결, 무엇이 다른가」, 4장 「질문하는 인간의 귀환」을 먼저 읽고 부록 B의 6주 코스를 곧바로 시작하라."},{"k":"p","t":"이 진단표의 목적은 독자를 줄 세우는 것이 아니다. 자기 위치를 알아야 지도가 작동한다. 제5의 물결은 모두에게 같은 높이로 오지 않지만 준비한 사람과 준비하지 않은 사람의 차이는 날마다 벌어지니, 점수를 적었다면 한 장만 더 넘기자. 왜 하필 지금 이 책이 당신에게 도착했는지, 그 이유부터 짚고 가야 한다. 점수가 낮게 나온 칸을 서둘러 덮지 말고 오늘 날짜만 옆에 적어 두면, 반년 뒤 같은 표를 다시 펼치는 저녁에 그 숫자는 부끄러움 대신 출발선의 좌표로 남는다."},{"k":"quote","t":"「현재 위치를 모르는 사람에게는 어떤 지도도 백지다.」"}],"no":9},{"part":"여는 물결","title":"문 앞의 세 사람 — 왜 하필 지금인가","sid":"s05","blocks":[{"k":"h","t":"문 앞의 세 사람: 왜 하필 지금, 이 책이 당신에게 도착했는가"},{"k":"p","t":"방금 점수를 적었다면, 잠깐 그 숫자를 손바닥으로 덮어 두자. 숫자보다 중요한 것이 하나 있다. 어느 문항 앞에서 펜이 멈췄는가. 사람은 자기가 모르는 것 앞에서가 아니라, 알면서 미뤄 둔 것 앞에서 멈춘다."},{"k":"p","t":"나는 지난 몇 해 동안 강단과 회의실과 시장 골목을 오가며 같은 파도 앞에 선 사람들을 봤다. 다르게 반응했다. 크게 세 부류였다."},{"k":"p","t":"첫 번째 사람은 파도를 검색한다. 기사 링크를 모으고, 유튜브 요약본을 저장하고, 단톡방에 공유한다. 아는 것은 매주 늘어나는데 바뀌는 것은 없다. 정보를 소비하는 일과 준비하는 일을 혼동한 채로 계절이 몇 번 지나간다."},{"k":"p","t":"두 번째 사람은 파도를 읽는다. 뉴스의 개수가 아니라 방향을 보고, 어제 기사와 오늘 기사 사이에서 물빛이 달라진 지점을 짚어 내는데, 어부가 하는 일이 꼭 그렇다. 파도를 세지 않는다. 결을 본다. 이 책이 파도 리딩이라 부르는 근육이다."},{"k":"p","t":"세 번째 사람은 파도를 지휘한다. 도구에게 목적을 건네고, 절차는 도구가 짜게 두고, 마지막 서명은 자기가 한다. 이 책은 그 자리를 AI 디렉터라 부른다. 현장에서 가장 바쁜 손은 카메라를 든 손이지만, 영화의 방향을 정하는 것은 “컷”을 외치는 목소리다. 세 사람은 같은 뉴스를 읽고 같은 도구를 켰지만 하나는 링크를 모았고 하나는 결을 읽었고 하나는 목적을 건넸으며, 그 저녁의 손놀림이 이후 십 년치 이력서를 미리 적어 두고 있었다."},{"k":"h","t":"십 년을 가르는 것은 재능이 아니었다"},{"k":"p","t":"셋의 차이는 머리가 아니었다. 스펙도, 나이도, 회사 이름도 아니었다. 아침마다 십 분을 어디에 쓰느냐였다."}],"no":10},{"part":"여는 물결","title":"문 앞의 세 사람 — 왜 하필 지금인가","sid":"s05","blocks":[{"k":"p","t":"첫 번째 사람은 그 십 분에 남의 요약을 읽었다. 두 번째 사람은 자기 일에 질문을 적었다. 세 번째 사람은 어제 맡긴 일의 결과를 검토하고 고쳐 보냈다. 같은 십 분이다. 그런데 일 년을 모으면 오백 시간이 넘고 십 년이면 다섯 달을 통째로 더 산 셈이지만, 이 격차는 통계에 잡히지도 뉴스가 되지도 않는다. 그래서 이 책은 그것을 조용한 격차라 부른다."},{"k":"p","t":"여기서 오해 하나를 미리 걷어내고 싶다. 이 책은 AI를 잘 쓰는 법을 알려 주는 매뉴얼이 아니다. 도구 사용법은 반년이면 낡는다. 대신 이 책이 붙드는 것은 그보다 오래 가는 질문, 무엇을 맡기고 무엇을 끝까지 내 손에 둘 것인가 하는 물음이고, 그 경계선을 그을 줄 아는 사람만이 도구가 바뀌어도 자리를 잃지 않는다."},{"k":"h","t":"왜 하필 지금이어야 했는지"},{"k":"p","t":"왜 하필 지금인가. 새 기술이 들어온 날과 그것을 다루는 규칙이 생기는 날은 결코 같지 않다. 인쇄술도 그랬고 자동차도 그랬다. 이번 간격은 대략 삼 년쯤 된다. 그 삼 년 동안 어떤 사람은 규칙 없는 운동장에서 먼저 달리고, 어떤 사람은 그 운동장에서 다친다. 우리는 지금 그 운동장 한복판에 서 있다."},{"k":"p","t":"이번 물결은 이전과 성질이 다르다. 지난 네 번의 물결이 인간의 손과 발과 연결을 확장했다면, 이번 물결은 판단의 절차를 넘겨받는데, 목적만 건네면 방법을 스스로 짜는 단계다. 이 책은 그것을 AI 자율화혁명이라 부른다. 도구가 스스로 순서를 정하기 시작하면, 사람에게 남는 일은 방향과 책임이다. 값은 정확히 그 자리에 붙는다. 삽과 계산기는 아무리 정교해져도 어디를 파고 어떤 숫자를 쓸지는 끝까지 사람에게 물었지만, 이번 도구는 초안과 목록과 결론까지 먼저 내놓은 뒤 사람에게는 그대로 둘지 말지 한 번만 묻는다."}],"no":11},{"part":"여는 물결","title":"문 앞의 세 사람 — 왜 하필 지금인가","sid":"s05","blocks":[{"k":"p","t":"그러니 불안은 부끄러운 감정이 아니다. 오히려 가장 정확한 계기판이다. 다만 계기판만 들여다보고 있으면 차는 움직이지 않는다. 이 책은 그 불안을 지도로 바꾸려고 쓰였다. 겁을 주려고 쓴 글이 아니라, 건널 방법을 적어 둔 글이다."},{"k":"h","t":"함께 변하는 종(種)"},{"k":"p","t":"마지막으로 한 가지만 더. 이 물결의 진짜 이름은 대체가 아니라 공진화다. 꽃은 벌을 부르려 색을 얻었고 벌은 꽃을 찾으려 눈을 얻었듯, AI는 인간이 남긴 문장으로 자랐고 인간은 AI와 주고받으며 생각하는 방식을 바꾸는 중이다. 서로가 서로의 환경이 된 종. 뒤에서 낱말집이 이 인간형에 이름을 붙여 줄 것이다."},{"k":"p","t":"그 종이 되는 데 필요한 것은 대단한 결심이 아니다. 오늘 저녁, 자기 일 하나를 AI가 더 잘하는 칸과 나만 할 수 있는 칸, 둘이 만나야 닿는 칸으로 갈라 보면 된다. 그거면 충분하다. 이 책 전체가 사실은 그 세 칸을 넓히고 좁히는 이야기다."},{"k":"p","t":"당신이 이 책을 집어 든 진짜 이유는 아마 미래가 궁금해서가 아닐 것이다. 지금 자리가 흔들려서다. 흔들림은 무너짐의 신호일 수도 있고, 배가 물살을 탄 신호일 수도 있다. 어느 쪽인지는 다음 몇 페이지에서 갈린다."},{"k":"p","t":"그러니 조금만 더 읽어 보자. 다음 장은 당신이 이미 물결 한가운데 서 있다는 사실을 확인하는 자리다. 오늘 아침 당신의 하루에서 그 증거를 찾아낼 것이다. 흔들리는 배 위에서는 누구도 우아하게 서 있지 못하지만, 무릎을 굽히고 물살의 리듬에 몸을 맡긴 사람만이 결국 갑판 위에서 다음 파도가 오는 방향을 먼저 읽어 낸다."},{"k":"quote","t":"「같은 파도 앞에서 셋의 자리를 가른 것은 재능이 아니라, 아침 십 분을 어디에 썼느냐였다.」"}],"no":12},{"part":"여는 물결","title":"먼저 보는 페이지 — 당신은 이미 물결 안에 있다","sid":"s06","blocks":[{"k":"h","t":"먼저 보는 페이지:\n당신은 이미 제5의 물결 안에 있다"},{"k":"p","t":"오늘 아침에도 세상은 조용히 바뀌었다. 누군가는 AI에게 회의록을 맡겼고, 누군가는 보고서 초안을 몇 초 만에 받았다. 누군가는 아이의 숙제를 확인했고, 누군가는 가게의 매출을 예측했다. 누군가는 하루에 두 시간이 더 생겼고, 누군가는 아무 일도 하지 않았는데 뒤처진 것 같은 불안을 느꼈다."},{"k":"p","t":"이상한 일이다. 같은 시대를 살고 있는데, 어떤 사람에게 AI는 기회가 되고, 어떤 사람에게는 압박이 된다. 그 차이는 기술 지식만의 차이가 아니다. 앞으로 내 일이 어떻게 바뀔지 아는 사람과 모르는 사람의 차이다. 내 돈이 어디서 새고 있는지, 내 데이터가 누구의 자산이 되는지, 아이에게 무엇을 먼저 가르쳐야 하는지 아는 사람과 모르는 사람의 차이다."},{"k":"p","t":"AI는 이제 먼 미래의 이야기가 아니다. 이미 당신의 이메일 안에 있고, 검색어 안에 있고, 회의실과 병원과 교실과 매장과 통장과 휴대폰 알림 속에 있다. 우리는 AI를 기다리는 시대가 아니라, 이미 AI와 함께 사는 시대에 들어왔다. 그래서 이제 질문은 달라져야 한다. “AI가 올까?”가 아니라 “나는 이 흐름을 읽고 있는가?”를 물어야 한다. 이메일의 첫 문장과 검색 결과의 순서와 지도 앱이 골라 준 경로는 이미 오래전부터 우리 판단의 일부를 대신해 왔는데, 우리는 그것을 기술이라 부르지 않고 그저 편리함이라 부르며 무심히 지나쳤다."},{"k":"p","t":"챗봇을 능숙하게 다루는 요령을 알려 주는 책이라면 이 책 말고도 많고 그런 책은 반년이면 개정판이 나오는데, 이 책은 그보다 더 근본적인 질문에서 출발한다. AI가 답을 쏟아내는 시대에 인간은 무엇을 물어야 하는가. 무엇을 맡기고, 무엇을 끝까지 붙들어야 하는가. 어디까지 활용하고, 어디서 멈춰야 하는가. 그리고 언제부터는 사용자가 아니라 지휘자가 되어야 하는가."}],"no":13},{"part":"여는 물결","title":"먼저 보는 페이지 — 당신은 이미 물결 안에 있다","sid":"s06","blocks":[{"k":"p","t":"아마 당신이 이 책을 펼친 이유도 비슷할 것이다. 내 일이 사라질까 봐. 내 아이가 뒤처질까 봐. 내 사업이 낡아질까 봐. 내 데이터와 시간이 나도 모르는 사이 누군가의 수익으로만 흘러갈까 봐."},{"k":"p","t":"그 불안을 부끄러워하지 않아도 된다. 제대로 읽으면 가장 빠른 신호다. 불안은 우리에게 “지금 그대로 있어도 괜찮은가?”라고 묻는데, 이 책은 그 불안을 겁으로 끝내지 않고 막연한 걱정을 오늘의 실행 계획으로 바꾸기 위해 쓰였다."},{"k":"p","t":"공포는 사람의 발을 묶지만, 지도를 가진 사람은 움직인다. 제5의 물결 앞에서 필요한 것은 거창한 결심이 아니다. 오늘 당장 바꿀 수 있는 작은 한 칸이다. 거창한 결심은 대개 사흘을 넘기지 못하고 흐지부지되지만, 오늘 저녁 회의록 하나를 다르게 정리해 본 손의 감각은 다음 주에도 그다음 달에도 몸에 남아 조용히 다음 칸을 연다."},{"k":"h","t":"이 책을 읽고 나면 당신에게 남는 다섯 매듭"},{"k":"p","t":"먼저, 지도가 하나 남는다. 내 일을 재설계하는 지도다. 무엇을 AI에게 맡기고 무엇을 인간의 판단으로 남겨야 하는지 구분하게 되는데, 이 구분을 할 줄 아는 사람은 쉽게 대체되지 않고, 오히려 AI를 지휘하는 사람이 된다. AI 공진화시대의 인간 프리미엄은 여기서 시작된다. 앞으로 중요한 사람은 AI를 무서워하는 사람이 아니라, AI를 방향 있게 움직이는 AI 디렉터다."},{"k":"p","t":"그다음, 데이터 권리에 대한 감각이 생긴다. 당신이 남긴 클릭과 검색, 취향과 이동, 말과 글은 단순한 흔적이 아니라 AI가 학습하고 기업이 수익을 만들고 플랫폼이 영향력을 키우는 재료다. 이 책은 묻는다. 데이터는 누구의 것인가. 그 가치는 누구에게 돌아가야 하는가. 우리는 편리함을 얻는 대신 무엇을 내주고 있는가."}],"no":14},{"part":"여는 물결","title":"먼저 보는 페이지 — 당신은 이미 물결 안에 있다","sid":"s06","blocks":[{"k":"p","t":"세 번째, 가르칠 순서가 보인다. 아이와 학생에게 AI 사용법을 익히게 하는 일도 물론 필요하지만, 그보다 먼저 심어 줘야 할 것이 따로 있으니 질문하는 힘, 검증하는 습관, 공감하는 태도, 책임지는 용기다. 앞으로 아이들에게 필요한 것은 도구를 빨리 익히는 능력만이 아니라, 도구가 아무리 좋아져도 스스로 생각하고 판단하는 힘이다."},{"k":"p","t":"네 번째, 회사와 도시의 첫 전환 지점이 보인다. AI 혁신은 거창한 발표문에서 시작되지 않는다. 회의록 하나, 고객 응대 하나, 교육 방식 하나, 돌봄 현장 하나에서 시작되고, 지역 상권, 콘텐츠, 출판, 행정, 복지, 의료 같은 실제 현장에서 무엇부터 바꿔야 하는지 보이기 시작한다. 다섯 번째, AI가 강해질수록 인간이 무엇으로 남아야 하는지 답하게 된다. 속도만으로는 부족하다. 효율만으로도 부족하다. 앞으로 더 귀해지는 것은 신뢰, 책임, 판단, 관계, 품격이다. AI가 더 똑똑해질수록 인간은 더 인간다워져야 한다. 그것이 기술의 시대에 사라지지 않는 사람의 힘이다."},{"k":"p","t":"이 다섯 가지를 얻기 위해 필요한 것은 대단한 각오가 아니다. 한 장을 읽고, 마음에 남는 한 문장을 적고, 오늘 바꿀 수 있는 한 가지 일을 실험하면 된다. 이 책은 생각으로 끝나는 책이 아니라, 다음 행동으로 넘어가게 하는 책이다. 한 장을 읽고 한 문장을 적고 한 가지를 바꿔 본 저녁이 한 해쯤 쌓이면, 어느 날 후배가 막힌 자리를 들고 왔을 때 당신 손이 머뭇거림 없이 첫 줄부터 짚어 내려간다."},{"k":"quote","t":"「한 장, 한 문장, 한 가지. 문명은 늘 그 정도의 크기로 바뀌기 시작했다.」"}],"no":15},{"part":"열쇠말","title":"먼저 만나는 낱말 다섯","sid":"s07","blocks":[{"k":"p","t":"이름이 없는 것은 대비할 수 없다. 이 책의 전제가 그것이다. 뒤에 쉰 개의 낱말이 실려 있는데, 그중 다섯만 먼저 골라 건넨다. 외울 것은 없다. 뜻만 한 번 스쳐 두면 된다."},{"k":"p","t":"AI 자율화혁명 — 시키는 대로 하는 단계는 지났다. 목적만 받으면 절차를 스스로 짜는 단계로 넘어가는 대전환이다."},{"k":"p","t":"AI 디렉터 — 답을 받아 적는 사람과, 목적을 건네고 마지막 서명을 하는 사람은 다르다. 뒤쪽이 디렉터다."},{"k":"p","t":"A·H·AH — AI가 더 잘하는 일이 A, 사람만이 할 수 있는 일이 H, 둘이 만나야 비로소 되는 일이 AH다. 내 일을 가르는 지도다."},{"k":"p","t":"판단 프리미엄 — 답이 흔해질수록 값은 답에서 떨어져 나와 판단에만 붙는다. 초안은 순식간에 나오지만, 그것을 내보낼지 정하는 자리에는 여전히 사람의 이름이 필요하다."},{"k":"p","t":"AI 공진화 사피엔스 — 꽃과 벌은 서로를 바꾸며 함께 왔다. AI와 인간도 그렇게 간다. 이미 우리가 그 종이다."},{"k":"p","t":"나머지 마흔다섯 개는 책 뒤 낱말집에 있다. 먼저 이름을 아는 사람이 먼저 값을 매긴다."}],"no":16},{"part":"프롤로그","title":"문명의 문 앞에서","sid":"s08","blocks":[{"k":"h","t":"프롤로그: 문명의 문 앞에서"},{"k":"p","t":"어느 날 아침, 한 아이가 숙제를 하다 말고 AI에게 묻는다."},{"k":"quote","t":"“나는 커서 무엇이 되어야 해?”"},{"k":"p","t":"화면에는 데이터 과학자, 로봇 윤리 디자이너, 기후 적응 컨설턴트, 창작 프로듀서 같은 직업명이 수십 개 떠오른다. 아이는 잠시 바라보다가 다시 묻는다."},{"k":"quote","t":"“그런데 나는 어떤 사람이 되어야 해?”"},{"k":"p","t":"그 질문을 바라보는 어른의 마음 한쪽에는 서늘한 바람이 분다. 어느 날 내 직업의 이름이 검색창 아래로 밀려나고, 내가 오래 쌓아온 시간이 한 줄의 자동화 명령으로 바뀔지도 모른다. 그런 막막함이다."},{"k":"p","t":"그래서 AI 시대의 두려움은 먼 미래의 공포가 아니라, 오늘 아침 책상 앞에 앉은 한 사람의 체온 가까이에 있다. 손에 닿을 만큼 가깝다."},{"k":"p","t":"이 질문 앞에서 멈춘 것은 AI가 아니다. 멈춘 것은 우리 문명이다. 우리는 너무 오래 무엇을 할 것인가만 물어왔고, 이제 그 물음이 바뀌어야 한다. 어떤 인간으로 살아갈 것인가."},{"k":"p","t":"AI 문명은 이미 움직이고 있다. 먼 데가 아니라 일상 속에서. 스마트폰 속 추천 알고리즘, 병원의 진단 보조 시스템, 회사의 자동 보고서, 학교의 AI 튜터, 예술가의 이미지 생성 도구, 소상공인의 자동 응대 챗봇. AI는 그렇게 조용히 인간의 하루 속으로 들어왔다."},{"k":"p","t":"가장 먼저 들여다봐야 할 것은 속도의 간극이다. 인간의 제도는 천천히 바뀌는데 기술은 매일 새로워진다. 학교는 아직 시험 중심으로 움직이고, 기업은 아직 직무 중심으로 사람을 뽑으며, 정치는 아직 과거의 언어로 미래를 설명한다. 그 사이에서 불안이 태어난다. 하지만 불안은 나쁜 것이 아니다. 제대로 읽으면 경고등이다. 이 책은 그 경고등을 끄자고 말하지 않는다. 오히려 그 불빛을 따라가 보자고 제안한다. 거기에 새로운 문명의 설계도가 있기 때문이다."}],"no":17},{"part":"프롤로그","title":"문명의 문 앞에서","sid":"s08","blocks":[{"k":"p","t":"AI는 인간에게 독인가 축복인가. 정답은 아직 없다. 우리가 어떤 원칙을 세우고, 어떤 제도를 만들고, 어떤 배움을 선택하느냐에 따라 그것은 독이 될 수도 있고 축복이 될 수도 있다. 아직 정해지지 않았다는 뜻이다. AI의 미래는 기계의 미래가 아니라 인간 선택의 미래다."},{"k":"p","t":"제5의 물결이라는 이름을 선택한 데는 이유가 있다. 농업혁명, 산업혁명, 정보혁명, 플랫폼혁명. 그 뒤를 이어 지금 다섯 번째 물결이 밀려오고 있다. 이 물결은 이전의 것들보다 빠르다. 넓다. 깊다. 바꾸는 것도 특정 산업 하나가 아니라 인간의 사고방식 자체다."},{"k":"p","t":"그 물결 앞에서 우리는 세 가지 선택을 할 수 있다. 경고등을 끄고 돌아눕는 손과 그 불빛을 따라 일어서는 발 사이에 놓인 것은 정보의 양이 아니라 오늘 밤 무엇을 할지 정하는 태도다. 설계도는 늘 그 틈에서 펼쳐졌다."},{"k":"p","t":"외면하거나, 휩쓸리거나, 파도 위에 서거나."},{"k":"p","t":"이 책은 세 번째 선택을 위해 쓰였다. 파도를 막으려 하지 않는다. 파도를 읽고, 파도를 타고, 파도가 지나간 자리에 남을 인간의 풍경을 함께 그려보려 한다. 문의 손잡이는 이미 우리 손에 있어서, 책장을 넘기는 순간 우리는 문 앞에 서 있는 것이 아니라 문 안쪽에 이미 들어서 있다."},{"k":"p","t":"이 책을 읽는 법 — 하루에 한 장씩 읽고, 각 장 말미의 작은 실험을 바로 적어 보라. 먼저 1장·5장·10장을 읽어 전체 지도를 잡고, 부록 B의 6주 워크북으로 행동을 고정하라. 읽는 동안 떠오른 질문 하나를 책 여백에 남겨라. 그 질문이 당신의 다음 전략이 된다. 당신의 다음 1년은 오늘과 분명히 달라질 것이다. 읽기만 하는 책이 아니라, 함께 걸어가는 책이 되기를 바란다."},{"k":"h","t":"첫 장을 넘기기 전, 딱 한 줄만 챙긴다면"}],"no":18},{"part":"프롤로그","title":"문명의 문 앞에서","sid":"s08","blocks":[{"k":"p","t":"AI는 인간의 자리를 빼앗기 위해 온 것이 아니라, 인간이 자기 자리를 다시 묻도록 만든 가장 거대한 질문이다. 그 질문을 남에게 맡기는 순간 우리는 지배당한다. 그 질문을 붙드는 순간 우리는 다시 지휘자가 된다. 문 안쪽으로 한 발을 들인 사람에게 남은 일은 물살을 탓하는 시간을 접고 오늘 저녁 노를 어느 쪽으로 저을지 정한 다음 그 방향을 손에 익히는 것이다."},{"k":"p","t":"앞서 펼쳐 본 목차는 단순한 순서표가 아니다. 지도다. 불안에서 출발해 제5의 물결의 정체, 삶의 전선, 개인 실행, 조직·산업·국가, 열 개의 시선, 윤리와 인간성, 마지막 질문으로 이동하는 문명의 지도. 목차를 따라 걷기 전에 이 문장 하나만 기억하라."},{"k":"quote","t":"“AI가 답을 내는 시대일수록, 인간은 더 좋은 질문으로 살아남는다.”"},{"k":"p","t":"이제 첫 장을 펼쳐도 좋다. 당신은 더 이상 구경꾼이 아니라, 제5의 물결 위에 서서 첫 노를 잡은 사람이다."},{"k":"p","t":"제5의 물결은 이미 시작되었다. 이제 남은 질문은 하나다. 당신은 그 파도를 바라만 볼 것인가, 그 위에 올라탈 것인가. 올라타기로 했다면 마지막으로 챙길 것이 하나 있다. 낱말이다. 새 문명은 늘 새 말을 데리고 오고, 말을 먼저 가진 쪽이 세계를 먼저 설명한다. 다음 쪽에 이 책을 여는 다섯 개의 열쇠말과 신문명 키워드 쉰 개를 펼쳐 두었으니, 배에 오르기 전 딱 한 번만 훑고 가자."}],"no":19},{"part":"저자의 말","title":"그래서, 그다음은요?","sid":"s09","blocks":[{"k":"h","t":"저자의 말"},{"k":"p","t":"몇 해 전이었다. 어느 강의장에서 4차 산업혁명을 두 시간 내내 이야기하고 마이크를 내려놓으려는데, 맨 뒷줄에 앉아 있던 한 청년이 손을 들었고 질문은 짧았다. “그래서, 그다음은요?” 나는 답하지 못했다. 슬라이드는 이미 마지막 장이었고, 준비해 온 문장도 거기서 동이 났다."},{"k":"p","t":"그날 밤, 돌아오는 길 내내 나는 그 한마디를 곱씹었다. 4차 산업혁명 이후의 다음 파도는 무엇인가. 『제5의 물결』은 그 질문에서 시작되었다. 모두가 눈앞의 파도에 휩쓸려 갈 때, 나는 그 파도가 지나간 자리가 궁금했다. 거기 무엇이 남는지. 정부 혁신의 흐름을 지나 디지털 전환의 폭풍 속을 걸어오는 동안에도 마음을 떠나지 않은 질문은 하나였다."},{"k":"quote","t":"“이 거대한 격변의 끝에는, 무엇이 기다리고 있는가?”"},{"k":"p","t":"가벼운 호기심이었다면 잊혔을 것이다. 그런데 잊히지 않았다. 강의와 포럼, 세미나와 정책 토론의 자리를 수십 년 오가는 동안 그 질문은 늘 나를 한 발짝 뒤에서 따라왔고, 답을 찾았다 싶으면 어김없이 다음 질문이 그 자리를 대신했다. 자료를 뒤졌다. 사람을 만났다. 틀렸다 싶으면 처음으로 돌아갔다. 그러다 어느 날, 답의 윤곽이 잡혔다."},{"k":"p","t":"4차 산업혁명이 채 끝나기도 전에, 다음 문명의 물결은 이미 시작되고 있었다. 기술 변화 하나로 설명될 일이 아니었다. 정부 혁신과 디지털 전환, 4차 산업혁명의 흐름이 사회 곳곳에 깊은 흔적을 남기던 그 시기에도 나는 같은 질문을 손에서 놓지 못했다."},{"k":"quote","t":"“그다음 파도는 무엇인가?”"}],"no":20},{"part":"저자의 말","title":"그래서, 그다음은요?","sid":"s09","blocks":[{"k":"p","t":"강의 현장에서, 토론의 자리에서, 자료와 사례를 하나씩 뒤집어 보면서 나는 산업 변화의 이면을 따라갔다. 기술의 진화가 인간의 삶과 문명의 구조를 어떻게 바꾸는지 보고 싶었다. 답은 뜻밖에 선명했다. 우리는 지금 기술 변화 하나로 설명하기 어려운 시대를 넘어, 인간과 AI, 산업과 문명, 국가와 개인의 질서가 통째로 재편되는 새로운 전환점 앞에 서 있다. 그 오랜 문제의식과 시대를 읽는 시선이 응축되어 나온 결과물이 바로 『제5의 물결』이다. 그 질문은 대답을 요구하기보다 자리를 지키는 쪽에 가까웠고, 자료를 덮고 강의장을 나서고 계절이 몇 번 바뀌는 동안에도 뒤에서 조용히 따라왔으며, 결국 나는 그것을 떨쳐 내는 대신 데리고 살기로 했다."},{"k":"p","t":"이 책은 미래를 멀찍이 바라보는 예측서가 아니라, 인류가 마주할 다음 세대의 거대한 패러다임을 증명하는 리포트이자, 격변의 파도 위에서 살아남을 사람들을 위한 가장 실전적인 나침반이다. 나는 AI 시대를 기술 혁신의 연장선으로 보지 않는다. 인간과 기업, 국가와 교육, 노동과 부(富)의 질서가 통째로 다시 설계되는 문명 전환의 신호로 읽는다. 다만 공식은 아니다. 이 원칙은 업종과 세대, 지역의 속도에 맞춰 다르게 적용되어야 한다."},{"k":"p","t":"이 책은 예측에서 멈추지 않는다. 다가올 AI 신문명 시대에 인간은 무엇을 준비해야 하는지, 기업과 국가는 어떤 전략으로 미래를 지휘해야 하는지를 묻고 답한다. 경고이자, 초대장이다."}],"no":21},{"part":"저자의 말","title":"그래서, 그다음은요?","sid":"s09","blocks":[{"k":"p","t":"세상의 변화는 예고 없이 찾아오지 않는다. 언제나 신호가 먼저 온다. 그 신호를 읽는 사람과 무시하는 사람의 차이가 다음 세대의 승자와 패자를 가른다. 나는 오랜 시간 현장에서 그 신호들을 하나씩 주워 모았고, 이 책은 그 신호를 당신의 손에 그대로 옮겨 놓기 위해 쓴 가장 정직한 시도다. 제5의 물결은 이미 우리 발끝에 닿아 있다. 문제는 올라탈 것인가, 휩쓸릴 것인가다. 다만 현실에서는 예산과 인력, 조직문화의 속도가 저마다 다르니 작게 검증한 첫 사례에서 시작하는 편이 안전하다."},{"k":"p","t":"파도는 멀리서 오지 않는다. 지금 이 순간, 이미 당신의 발끝에 닿아 있다. 한 페이지를 펼치는 일. 그 작은 결정이 다음 10년의 당신을 만든다. 이 책을 예측서로 읽으면 몇 장 넘기다 실망할 테지만 나침반으로 쥐면 페이지마다 지금 서 있는 자리가 먼저 보일 텐데, 걸음의 보폭과 방향은 끝내 읽는 사람 몫이다."},{"k":"p","t":"세상 만물에는 저마다 존재하는 이유가 있고, 인간의 곁에 AI가 와 준 데에도 이유가 있을 텐데, AI가 어디서 와서 어디로 가느냐는 우리가 그것을 어떻게 쓰느냐에 달려 있다. 인류의 새로운 문명으로 쓸 것인가, 마지막이 되게 할 것인가. 그 선택은 사람만이 한다. 그날 강의장의 청년에게 뒤늦게 건네는 대답이자, 이 책이 세상에 묻고 답하는 이유다."},{"k":"p","t":"— 저자 드림"}],"no":22},{"part":"읽는 법","title":"다섯 가지 독서 경로와 6주 실행 코스","sid":"s10","blocks":[{"k":"h","t":"이 책을 읽는 법:\n다섯 가지 독서 경로와 6주 실행 코스"},{"k":"p","t":"이 책은 처음부터 끝까지 읽어도 좋다. 하지만 꼭 그렇게만 읽을 필요는 없다. 지금 당신에게 가장 급한 질문이 있을 것이다."},{"k":"quote","t":"“내 일자리는 괜찮을까?”"},{"k":"quote","t":"“AI 시대에 사업 기회는 어디에 있을까?”"},{"k":"quote","t":"“아이에게 무엇을 가르쳐야 할까?”"},{"k":"quote","t":"“우리 조직과 지역은 무엇을 준비해야 할까?”"},{"k":"quote","t":"“창작자는 AI와 어떻게 함께 일해야 할까?”"},{"k":"p","t":"그 질문에서 시작하면 된다. 이 책은 한 줄로 곧게 뻗은 길이 아니라, 독자의 상황에 따라 다시 펼쳐볼 수 있는 지도에 가깝다."},{"k":"p","t":"바쁜 직장인이라면 1장 → 4장 → 10장 → 11장 → 부록 B를 먼저 읽어보라. 막연한 불안이 어디서 오는지 확인하고, AI 시대에 인간이 붙잡아야 할 질문의 기준을 세울 수 있다. 이어서 AI 리터러시와 에이전트 활용법을 6주 실행 코스로 옮기면, 불안은 조금씩 행동으로 바뀐다."},{"k":"p","t":"창업가와 사업가라면 2장 → 5장 → 10장 → 11장 → 12장 → 13장 → 14장 → 17장 → 부록 A를 추천한다. 이 길은 제5의 물결이 이전 변화와 무엇이 다른지 보여주고, 일의 방식, 개인 브랜드, 사업 기회, 전환 전략을 하나의 흐름으로 연결해준다. AI를 단순한 도구가 아니라 새로운 사업 지도로 보고 싶은 사람에게 알맞다."},{"k":"p","t":"부모와 교육자라면 3장 → 4장 → 21장 → 23장 → 31장 → 33장을 먼저 읽어보라. 아이에게 필요한 것은 단순한 AI 사용법만이 아니다. 질문하는 힘, 판단하는 힘, 책임지는 태도다. 이 경로는 AI 시대의 교육이 어디서부터 다시 시작되어야 하는지 차분히 짚어준다. 지도를 펴는 사람은 모든 길을 다 걷지 않고 오늘 당장 급한 길부터 손가락으로 짚는데, 이 책도 그렇게 읽어서 가장 자주 떠오르는 질문이 적힌 장부터 펼치면 된다."}],"no":23},{"part":"읽는 법","title":"다섯 가지 독서 경로와 6주 실행 코스","sid":"s10","blocks":[{"k":"p","t":"정책, 공공, 지자체 분야의 독자라면 15장 → 16장 → 17장 → 18장 → 19장 → 20장 → 31장을 먼저 읽는 것이 좋다. 이 길은 제도 지체, 국가 전략, 중소기업, 의료와 복지, 교육과 출판, 로컬 전환, 윤리 기준을 하나의 큰 의제로 묶어준다. AI를 개인의 문제가 아니라 사회 전체의 전환 과제로 바라보게 만든다."},{"k":"p","t":"크리에이터와 강연자라면 12장 → 13장 → 10장 → 25장 → 26장 → 부록 A를 먼저 펼쳐보라. 1인 창작자가 AI를 어떻게 자신의 슈퍼팀으로 만들 수 있는지, 그리고 복제본이 넘쳐나는 시대에 어떻게 자기만의 목소리와 창의성을 지킬 수 있는지 확인할 수 있다."},{"k":"p","t":"어느 길을 선택하든 마지막에는 부록 B의 6주 실행 코스로 돌아가라. 한 장을 읽고, 한 문장을 적고, 한 가지 실험을 정해보라. 그 순간 이 책은 읽고 끝나는 책이 아니라, 당신의 다음 1년을 바꾸는 실행 노트가 된다."},{"k":"p","t":"“이 책은 한 번 읽고 덮는 책이 아니라, 불안이 올라올 때마다 다시 펼치는 지도다. 오늘은 생존의 장을 읽고, 내일은 사업의 장을 읽어도 좋다. 어느 날은 인간의 장 앞에 오래 머물러도 좋다. 많이 읽는 게 목표가 아니다. 읽고 난 뒤 당신의 질문이 달라지면 된다.”"},{"k":"p","t":"이 책은 일곱 부와 서른일곱 장으로 구성되어 있다. 각 장에는 현장의 사례, 세계가 보내는 신호, 한국 사회에 적용할 수 있는 포인트, 사업화 관점, 그리고 독자가 바로 해볼 수 있는 실행 과제를 담았다. 한 장을 읽고 나면 막연한 불안보다 “그럼 오늘 나는 무엇을 해볼까?”라는 문장이 남도록 설계했다."},{"k":"h","t":"『제5의 물결』 약속도 — 책 전체 흐름"},{"k":"p","t":"이 책은 일곱 개의 파도와 서른일곱 개의 물마루로 이루어진다."}],"no":24},{"part":"읽는 법","title":"다섯 가지 독서 경로와 6주 실행 코스","sid":"s10","blocks":[{"k":"p","t":"첫 번째 파도는 문명의 정체를 묻는다. 두 번째 파도는 삶과 일의 전선을 살핀다. 세 번째 파도는 개인이 무엇을 실행해야 하는지 보여준다. 네 번째 파도는 산업과 국가의 변화를 다룬다. 다섯 번째 파도는 열 개의 시선으로 AI 시대를 다시 읽는다. 여섯 번째 파도는 윤리와 책임의 문제를 묻는다. 일곱 번째 파도는 인간과 미래의 방향을 향해 나아간다."},{"k":"p","t":"이 흐름은 책 전체의 GPS다. 읽다가 길을 잃었다고 느껴질 때마다 다시 펼쳐보면 지금 내가 어느 파도 위에 있는지, 다음에 어디로 가야 하는지 알 수 있을 것이다."}],"no":25},{"part":"제1부","title":"문명의 문턱에 선 인간 — 부 도입","sid":"s11","blocks":[{"k":"h","t":"제1부"},{"k":"h","t":"문명의 문턱에 선 인간"},{"k":"p","t":"새벽 다섯 시. 식탁 위 노트북이 혼자 깨어 있고, 아이는 화면을 흘깃 보더니 왜 아직도 이걸 직접 쓰냐고 묻는다. 요란한 소리는 없었다. 책상 위의 일과 아이의 질문이 조금씩 다른 방식으로 움직이는 그 조용한 흔들림 속에서, AI 문명은 왜 하필 지금 우리 삶을 다시 묻는가."},{"k":"p","t":"노트북을 덮고 나서도 그 질문은 남는다. 전환의 속도를 만드는 건 기계가 아니라, 기계 앞에서 사람이 던지는 질문이다. AI 문명이라는 말의 정체가 무엇인지, 앞선 네 번의 물결과 제5의 물결이 어디에서 갈라지는지를 먼저 손에 쥐지 않으면 우리는 경계선 위에 서 있으면서도 자신이 어디쯤 서 있는지 끝내 모른다. 그래서 이 책은 첫 장부터 당신에게 묻는다. 왜 하필 지금인가."},{"k":"h","t":"이 부에서 먼저 붙잡을 세 매듭"},{"k":"p","t":"1) AI 문명이 왜 지금 폭발했는지 이해한다. 2) 제5의 물결이 이전 혁명과 다른 이유를 구분한다. 3) 질문하는 인간이라는 책의 핵심 메시지를 초반에 붙든다. 책상 위 서류의 결재선은 그대로여도 그 첫 문장을 누가 쓰느냐는 이미 달라졌다. 문명의 문턱은 늘 이런 손끝의 변화로 먼저 넘어온다."}],"no":26},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"1장"},{"k":"h","t":"왜 지금 AI 문명인가:\n가장 먼저 알아야 할 단 하나의 룰"},{"k":"p","t":"어느 날 업무 메신저에 올라온 초안이 동료의 문장인지 AI의 문장인지 구분하기 어려워졌다. 그 순간 질문은 바뀐다. 내 일이 언제 사라질지가 아니라, 나는 무엇을 맡기고 무엇을 끝까지 책임질 것인가."},{"k":"p","t":"강연장에서 가장 자주 받는 질문은 늘 비슷하다. “선생님, 그래서 제 일은 언제 사라지나요?” 어느 중소기업 워크숍에서 한 40대 팀장이 손을 들고 그렇게 물었을 때, 강의실의 공기가 잠깐 멈췄다. 모두가 같은 질문을 마음에 품고 있었던 것이다."},{"k":"p","t":"나는 답 대신 되물었다. “언제 사라지느냐보다, 그때까지 무엇을 남길 것인가를 먼저 정해두면 어떨까요?” 질문이 바뀌자 표정이 바뀌었고, 두려움이 계획으로 옮겨가는 그 짧은 순간이 이 책이 말하려는 전부인데, ‘왜 지금인가’라는 물음은 한가한 진단이 아니라 오늘 당장 손에 쥘 수 있는 출발선이다."},{"k":"h","t":"닷새 만에 100만 명, 두 달 만에 1억 명"},{"k":"p","t":"2022년 11월 30일. 한 웹사이트가 조용히 열렸다. 특별한 이벤트도, 요란한 광고도 없었다. 그런데 닷새 만에 100만 명이 접속했고, 두 달 만에는 이용자 1억 명에 이른 것으로 추정됐으니, 인터넷 역사상 가장 빠른 성장이었다. 그 웹사이트의 이름은 ChatGPT였다."},{"k":"p","t":"그 이전에도 AI는 있었다. 체스를 두었고, 바둑을 이겼으며, 의료 이미지를 분석했다. 그런데 ChatGPT가 달랐던 것은 언어였는데, 인간의 말로 인간과 대화하는 AI가 등장하면서 전문가의 영역으로만 여겨지던 지식 생산이 갑자기 모든 사람의 손 안으로 들어왔다."}],"no":27},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"이것이 왜 문명의 전환인가. 도구 하나가 추가된 사건이 아니기 때문이다. 글을 쓰고, 코드를 짜고, 음악을 만들고, 법률 문서를 검토하고, 의학적 소견을 정리하는 일까지 — 이 모든 것이 이제 AI와 함께, 혹은 AI를 통해 이루어진다. 증기기관이 근육의 한계를 넘어섰듯, AI는 지적 노동의 한계를 넘어서고 있다. 증기기관 앞에서 사람들이 물었던 것은 기계가 얼마나 힘이 센가였지만, 지금 우리가 물어야 할 것은 저 언어의 기계가 얼마나 똑똑한가가 아니라 그것과 마주 앉은 내가 무엇을 끝까지 놓지 않을 것인가다."},{"k":"note","t":"※ ChatGPT가 출시 닷새 만에 100만 사용자를 넘어섰다는 사실은 2022년 12월 5일 샘 올트먼 OpenAI CEO가 직접 밝힌 내용이다(X 게시물, 2022.12.5). 나란히 놓아 보면 넷플릭스는 구독 서비스를 시작한 1999년을 기준으로 같은 수준에 이르는 데 약 3.5년, 인스타그램은 76일(약 두 달 반)이 걸렸다(TechCrunch, 2010.12.21)."},{"k":"h","t":"왜 하필 지금인가 — 세 가지 기술의 수렴"},{"k":"p","t":"AI가 하필 지금 터진 데는 우연이 없다. 세 가지 기술이 한 점에서 만났다."},{"k":"p","t":"우선, 데이터의 폭발이다. 인터넷과 스마트폰이 지난 20년간 생산한 데이터의 양은 인류 전체 역사가 누적한 정보보다 많다. AI는 이 데이터를 먹고 자란다. 학습할 데이터가 충분해졌을 때, AI는 비로소 도약했다."}],"no":28},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"이어서, 연산력의 혁명이다. GPU 기술의 발전은 AI를 값싸게 ‘쓰게’ 만들었다. GPT-3.5 수준의 성능을 내는 데 드는 추론 비용은 2022년 11월부터 2024년 10월까지 약 280배 떨어졌다(Stanford HAI, 「2025 AI Index」). 다만 최전선 모델을 새로 ‘학습시키는’ 비용은 반대로 2016년 이후 해마다 약 2.4배씩 올라, GPT-4급 학습에는 수천만 달러가 든다(Epoch AI, 2024). 쓰는 값은 내려가고 만드는 값은 올라간다. 이 비대칭이 오늘의 지형을 만들었다."},{"k":"note","t":"※ NVIDIA 시가총액은 2020년 말 약 3,200억 달러에서 2024년 6월 5일 처음으로 3조 달러를 넘어섰다. AI 반도체 수요가 이 성장을 이끌었다."},{"k":"p","t":"세 번째로, 알고리즘의 도약이다. 2017년 구글 연구진이 주도해 발표한 트랜스포머 구조는 AI가 언어를 이해하는 방식을 뿌리부터 바꿨는데, 순서대로 단어를 처리하는 것이 아니라 문장 전체를 한꺼번에 보고 관계를 파악하는 방식이다. GPT와 BERT, LLaMA 같은 오늘의 거대 언어 모델은 모두 이 아이디어에서 출발했다."},{"k":"p","t":"세 가지가 같은 시기에 한 점으로 모였다. 그 점에서 ChatGPT가 태어났다. 우리는 우연한 한 순간이 아니라, 25년에 걸친 누적의 결과를 보고 있다."},{"k":"h","t":"순간, 소리 없이 뒤바뀌는 세계의 축"},{"k":"p","t":"역사가 우리에게 남긴 가장 기만적인 버릇은, 결정적 전환점의 순간에 언제나 침묵한다는 점이다. 거대한 변화는 축제처럼 오지 않는다. 밤새 내린 서리처럼 조용히 세상을 뒤덮을 뿐이어서, 인류는 늘 한 세대가 지나고 나서야 “아, 그때 시대의 축이 이동했구나” 하고 뒤늦게 깨닫는다."}],"no":29},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"1440년 요하네스 구텐베르크가 마인츠의 작은 작업장에서 포도 압착기를 개조해 활판 인쇄기를 두드릴 때, 그것이 신의 대리인들이 지배하던 중세를 무너뜨릴 전환점이 되리라 예상한 사람은 아무도 없었다. 종교개혁과 과학혁명이라는 해일이 그 작은 쇳조각에서 비롯되었음을, 당대의 지식인들조차 알아채지 못했다."},{"k":"p","t":"1769년도 마찬가지였다. 제임스 와트가 증기기관의 효율을 높여 특허를 취득했을 때, 사람들은 그저 광산의 물을 조금 더 빨리 퍼낼 수 있게 되었다며 기뻐했을 뿐이다. 그 기계 장치가 수천 년간 이어져 온 농경 사회를 해체하고, 거대한 도시를 건설하며, 인류의 계급 구조 자체를 뒤흔들 산업혁명의 서막이라는 것을 상상한 이는 없었다."},{"k":"p","t":"역사는 늘 그렇게 인간의 뒤통수를 치며 은밀하게 전진해 왔다. 그러나 이번에는 다르다. 단 한 가지 치명적인 차이가 있다. 속도다. 과거의 변화가 인간이 적응하도록 숨 고를 시간을 주었다면, 지금 우리 앞에 닥친 변화는 그 긴 숨 고르기를 허락하지 않는다. 인쇄술이 인류의 지식 지형을 바꾸는 데는 꼬박 100년이 필요했다. 그 시간 동안 인간은 법을 바꾸고, 제도를 정비하며, 새 시대에 적응할 마음의 준비를 마칠 수 있었다."},{"k":"p","t":"인공지능은 다르다. 이 불청객은 단 10년, 어쩌면 그보다 짧은 시간 안에 인간이 수백 년간 독점해 온 ‘지적 노동’의 방식을 통째로 재구성하고 있다. 질문을 던져야 한다. 왜 하필 지금인가."}],"no":30},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"답은 명확하면서도 서늘하다. 기술이 인간의 육체를 넘어, 인류의 마지막 보루였던 ‘지적 능력’을 보완하는 단계를 지나 본격적으로 대체하기 시작했기 때문이다. 기계가 스스로 생각하고, 창작하며, 판단을 내리는 시대. 그 진화의 속도는 인류가 방어벽을 세우고 대비할 여유조차 허락하지 않을 만큼 압도적이어서, 우리는 지금, 역사상 가장 빠르고 가차 없는 전환점의 한복판을 관통하는 중이다. 시대의 축이 이동하는 소리가 들리지 않는가."},{"k":"h","t":"숫자가 말하지 못하는 영역"},{"k":"p","t":"당신이 이 첫 문장을 읽는 지금 이 순간에도, 그것은 이미 당신 곁에 누워 있다. 같은 이불을 덮은 채로."},{"k":"p","t":"2022년 11월. 세상이 발칵 뒤집혔던 그 차가운 아침을 기억하는가. 무엇을 물어도 살아 있는 사람처럼 막힘없이 답을 건네던 ChatGPT가 세상에 첫발을 디딘 지, 벌써 3년 반이 흘렀다. 속절없이."},{"k":"p","t":"2026년 2월, OpenAI가 조용히 꺼내 든 숫자는 9억이었다. 주간 활성 사용자 9억 명. 서비스 하나가 지구 위 인류의 10분의 1을 제 영토로 삼아버렸는데, 그것도 제미나이니 클로드니 하는 다른 거인들의 땅은 아예 빼고 센 숫자가 그렇다. 그리고 넉 달 뒤, ChatGPT의 월간 앱 사용자는 10억 명을 넘어섰다."},{"k":"p","t":"그 아득한 시간 동안, 우리 삶에는 대체 무슨 일이 벌어진 걸까. 성공한 플랫폼의 신화처럼 보이는 이 거대한 숫자 뒤에는, 실은 전혀 다른 뜨거운 진실이 숨어 있다. 중요한 건 ‘얼마나 많이 가입했느냐’가 아니다. ‘얼마나 자주, 얼마나 깊숙이 만지고 있느냐’다."}],"no":31},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"마이크로소프트와 링크드인이 31개국 3만 1천 명을 조사한 「Work Trend Index 2024」는 서늘할 만큼 흥미로운 장면 하나를 가리킨다. 한국의 지식노동자 열 명 중 일곱 명, 정확히는 73%가 이미 업무에 AI를 쓰고 있었다(2024년 5월 발표). 불과 3년 전만 해도 얼리어답터들의 장난감이던 것이."},{"k":"p","t":"숫자는 언제나 얼음처럼 차갑다. 기계적이고, 메마르고, 표정이 없다. 그러나 그 무미건조한 숫자의 행간을, 아주 가만히 들여다보라. 거기, 붉어진 눈으로 출근해 “이 메일 영어로 좀 부드럽게 고쳐줘” 하고 나직이 속삭이는 옆자리 김 대리가 서 있다. 마감 직전, 하얗게 질린 얼굴로 모니터 앞에서 초안을 쥐어짜 내는 성실한 후배가 있다. 늦은 밤, 아이의 서툰 일기를 다정하게 매만지는 배우자의 굽은 등이 그 숫자의 픽셀 속에 조용히 겹쳐 있다."},{"k":"p","t":"변화는 혁명의 깃발을 흔들며 요란하게 오지 않았다. 그저 매일 반복되는 소박한 루틴 속으로, 소리 하나 내지 않고 스며들었을 뿐이다. 우리는 여전히 그것을 ‘문명의 이기(利器)’라 부르며 애써 선을 긋는다. 하지만 마음 깊은 곳에서는 이미 안다. 우리는 그저, 이미 우리 삶이 되어버린 거대한 파도에 뒤늦게 이름표 하나를 붙이고 있을 뿐이라는 것을. 돌아보면 우리가 파도를 처음 만난 날은 뉴스가 떠들썩하던 어느 아침이 아니라, 아무 일도 없다는 듯 메일 한 통을 고쳐 쓰고 아이의 일기를 다듬던 그 평범한 저녁이었다."},{"k":"h","t":"싱가포르는 AI 교육을 복지가 아니라 인프라로 봤다"}],"no":32},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"싱가포르는 시민 AI 리터러시를 복지 혜택이 아니라 국가 인프라로 설계했다. 국가 프로그램 ‘AI 싱가포르’가 만든 무료 입문 과정 ‘모두를 위한 AI(AI for Everyone)’는 개발자 양성 강좌가 아니다. 회사원과 자영업자, 은퇴자까지 누구나 반나절이면 AI의 원리와 한계를 몸에 익히도록 설계된 공공형 학습 입구다."},{"k":"p","t":"이 사례가 남기는 것은 강좌 하나가 아니라 사다리다. 입문을 마친 시민은 ‘산업을 위한 AI’ 같은 심화 단계로 올라서고, 국가는 그 계단을 무료로 받쳐 준다. 도시국가의 작은 몸집이 오히려 증명한다. 기술 강대국이 아니어도, 배움의 계단을 먼저 놓는 나라가 문명의 계단을 먼저 오른다는 것을. 핀란드가 시민 캠페인으로 문을 열었다면(2장에서 다시 만난다), 싱가포르는 국가 스킬 사다리로 층계를 놓았다."},{"k":"note","t":"※ AI 싱가포르(AI Singapore)는 2017년 싱가포르 국가연구재단(NRF) 주도로 출범한 국가 AI 프로그램이며, ‘모두를 위한 AI(AI for Everyone)’는 일반 시민 대상 무료 입문 과정으로 운영되어 왔다(AI Singapore 공식 프로그램 안내)."},{"k":"h","t":"우리에게 이미 있는 네 가지 자산"},{"k":"p","t":"한국은 이 물결을 늦게 탄 사회가 아니다. 디지털 적응력, 교육열, 콘텐츠 역량, 촘촘한 소상공인 생태계는 실질적인 자산이다. 그러나 위험도 분명하다. 고령화로 학습 격차가 벌어지고, 수도권 집중으로 기회의 지도가 기울어지며, 시험 중심 교육이 질문하는 능력을 늦게 키운다. 중소기업은 인력과 자본의 동시 부족 속에서 AI 도입을 미루고 있다."},{"k":"p","t":"해법은 거대한 국가 계획이 아니다. 작은 입구를 많이 여는 일이다. 동네 도서관에 AI 코너를, 노인복지관에 챗봇 사용법 수업을, 소상공인 협동조합에 공동 AI 도구를. 입구가 많을수록 사회는 천천히, 그러나 빠짐없이 적응한다."}],"no":33},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"h","t":"지금 가장 잘 팔리는 상품은 시간이다"},{"k":"p","t":"사업가의 관점에서 첫 번째 장은 한 가지를 가르친다. 지금 가장 잘 팔리는 상품은 ‘시간’이다."},{"k":"p","t":"예시 1은 직장인용 ‘AI 회의록 한 장 요약’ 구독 서비스다. 1시간 회의를 3분 안에 결정 사항·할 일·위험으로 정리한다. 예시 2는 부모용 ‘AI 가정학습 코디네이터’로, 아이의 학습 데이터를 바탕으로 부모가 일주일에 30분만 들여도 학습 흐름을 잡을 수 있게 설계한다. 예시 3은 자영업자용 ‘매일 5분 매장 리포트’다. 매출과 재고, 리뷰와 날씨, 인근 행사 정보를 AI가 묶어 사장에게 음성으로 읽어준다."},{"k":"p","t":"세 가지에는 공통된 결이 있다. AI가 시간을 만들고, 인간이 그 시간으로 더 좋은 결정을 내리도록 설계한다는 것이다."},{"k":"h","t":"생활 현장에서 본 신호"},{"k":"p","t":"강의실에서 건져 올린 장면 — 강의장에서 이 대목을 꺼내면, 참석자들은 대개 “내 일도 정말 바뀌나요?”라고 먼저 묻는다. 그 질문이야말로 변화가 이미 생활의 문턱까지 왔다는 가장 솔직한 신호다."},{"k":"p","t":"새벽 여섯 시. 작은 카페의 사장이 매장 문을 열기 전 휴대폰을 켠다."},{"k":"quote","t":"“오늘 매출 어떻게 될 것 같아?”"},{"k":"p","t":"AI가 답한다. 어제 날씨, 어제 매출, 인근 학원 일정, 이번 주 강수 확률을 분석해 오늘 예상 매출을 알려준다. 추천 메뉴 문구도 함께 보낸다. 사장은 잠시 망설인다. 어제까지 감으로 하던 일이 오늘은 대화로 바뀐다."}],"no":34},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"그는 AI의 추천을 100% 따르지 않는데, 단골이 어떤 표정이었는지, 옆 가게 사장과 어떤 대화를 했는지는 AI가 모른다는 걸 알기 때문이다. 숫자 위에 자기 감각을 얹는다. 작은 가게의 불빛 아래에서 문명의 방향이 그렇게 조용히 움직인다. 새벽 여섯 시의 그 작은 결정은 어느 보고서에도 기록되지 않겠지만, 기계가 내민 숫자를 받아들고 마지막 한 줄을 자기 손으로 고쳐 쓰는 사람이 늘어나는 만큼 이 문명의 방향도 조금씩 사람 쪽으로 기운다."},{"k":"h","t":"연필을 들어야 할 다섯 칸 — 내 일의 AI 등고선"},{"k":"p","t":"아래 다섯 질문을 천천히 채워 보자. 한 번에 완벽하게 채울 필요는 없다. 일주일 동안 매일 한 칸씩 다듬어도 좋다."},{"k":"p","t":"[1칸] 내가 하루에 가장 오래 하는 지적 노동은 무엇인가. [2칸] 그 노동 중 단순 반복은 어떤 부분인가. [3칸] 그 노동 중 사람이 먼저 해야 하는 부분은 무엇인가. [4칸] 만약 2칸을 AI에 맡긴다면, 그 시간으로 무엇을 할 것인가. [5칸] 3칸의 능력을 더 깊게 키우기 위해 이번 달에 시작할 학습 한 가지는 무엇인가."},{"k":"p","t":"이 다섯 칸이 채워지면 당신은 AI 시대의 가장 중요한 자산을 손에 쥔 셈이다. 자기 일의 지도. 다른 사람의 지도가 아니라 자기 자신의 지도다."},{"k":"h","t":"오늘 세 가지 업무 옆에 숫자를 적어 보라"},{"k":"p","t":"오늘 한 업무 세 가지를 적고, 각 업무 옆에 “AI 보조 가능성”을 0·50·100% 중 하나로 표시해 보라. 마지막 칸에는 사람이 직접 판단해야 할 이유를 한 줄로 남겨라."},{"k":"p","t":"이번 주 하루만 골라 보자. 그 하루 동안 당신이 한 일 중 ‘AI에게 맡길 수 있었던 것’ 세 가지를 적고, 이어서 ‘AI에게 맡기지 않아 다행이었던 것’ 세 가지를 적는다. 두 목록의 차이를 보는 순간, 당신만의 전략이 보인다."},{"k":"h","t":"이 장을 한 문장으로 남긴다면"}],"no":35},{"part":"제1부 1장","title":"왜 지금 AI 문명인가","sid":"s12","blocks":[{"k":"p","t":"기술의 변화가 아니라 인간 지능의 외주화가 시작되었다. 무엇을 맡기고 무엇을 남길지 결정하는 사람이 다음 10년을 산다. 맡길 목록과 남길 목록을 각각 한 장에 적어 둔 사람은 이미 다음 장의 문턱을 넘은 셈이며, 그 문턱 너머에는 앞선 네 번의 파도와 이번 파도가 무엇이 다른지를 묻는 자리가 놓여 있다."},{"k":"quote","t":"「파도는 모두에게 온다. 갈리는 것은 파도가 아니라, 젖기 전에 무엇을 물었느냐다.」"},{"k":"quote","t":"「지금이 ‘처음으로 도구가 도구 사용자가 된’ 첫 순간이다.」"}],"no":36},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"2장"},{"k":"h","t":"제5의 물결, 무엇이 다른가"},{"k":"p","t":"빠른 답은 이제 누구나 얻는다. 오래 살아남는 사람은 답이 놓친 맥락을 다시 묻는 사람이고, 때로는 빠른 답 하나보다 끝까지 붙들고 간 질문 하나가 내일의 판단을 구한다. 『제5의 물결』은 속도를 겨루는 시대를 넘어, 판단을 단련하는 시대로 우리를 이끄는 파도다."},{"k":"p","t":"이제 인간과, 한때 도구라 불리던 AI는 전례 없는 공진화의 문턱에 서 있다. 그 거대한 흐름은 우리 앞에 ‘공진화 사피엔스’라는 새로운 파도로 다가오고 있다."},{"k":"h","t":"토플러가 열지 못한 다섯 번째 파도"},{"k":"p","t":"1980년, 앨빈 토플러는 『제3의 물결』을 냈다. 농업혁명을 제1의 물결, 산업혁명을 제2의 물결, 정보혁명을 제3의 물결이라 불렀다. 그의 예측은 정확했다. 인터넷이 세상을 바꿨고, 정보가 권력이 되었다."},{"k":"p","t":"이후 학자들은 제4의 물결을 정의했다. 플랫폼 혁명이다. 아마존, 구글, 애플, 메타. 이 플랫폼 기업들이 시장을 재편했다. 사람들은 소비자이자 공급자가 되었고, 데이터가 새로운 석유가 되었다."},{"k":"p","t":"그리고 지금, 제5의 물결이 밀려온다. 이번 물결의 이름은 AI 자율화 혁명이다. 이전 물결들이 인간의 행동을 도왔다면, 이번 물결은 인간의 생각을 돕고, 나아가 인간 없이도 특정 생각을 대신 수행한다. 토플러는 정보의 파도를 봤다. 그러나 그 정보가 스스로 판단하고 행동하는 단계까지는 열지 못했다. 그가 남긴 지도의 가장자리에서 길이 뚝 끊긴 자리, 정보가 스스로 판단을 시작하는 바로 그 지점이 우리가 지금 첫 발자국을 찍어야 하는 이름 없는 해안선이고, 제5의 물결은 거기서부터 밀려온다."},{"k":"h","t":"다섯 물결의 비교표"},{"k":"p","t":"각 물결은 인간의 어떤 능력을 확장했는가. 이 질문에 답해 보면 차이가 선명해진다."}],"no":37},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"제1의 물결, 농업혁명. 근육을 대지에 심었다. 인간은 정착했고 잉여 식량이 문명을 낳았다. 제2의 물결, 산업혁명. 근육을 기계로 증폭했다. 공장이 등장했고 도시가 폭발했다. 제3의 물결, 정보혁명. 정보를 전 세계로 연결했다. 지식이 국경을 넘었다. 제4의 물결, 플랫폼혁명. 관계와 소비를 디지털화했다. 모든 거래가 데이터의 흔적을 남겼다. 제5의 물결, 인공지능혁명. 판단하고 추론하고 창작하는 능력을 기계에 이식한다. 도구가 처음으로 도구 사용자가 된다."},{"k":"p","t":"앞의 네 물결이 인간의 ‘능력’을 늘렸다면, 다섯 번째 물결은 인간의 ‘판단’ 자리에 손을 댄다. 우리가 지켜야 할 것도 능력이 아니라 판단인 셈이다."},{"k":"h","t":"이전과 다른 세 가지 갈림길"},{"k":"p","t":"다섯 번째 물결의 차이는 세 갈래로 정리된다."},{"k":"p","t":"첫째, 속도의 차원이 다르다. 농업혁명은 수천 년에 걸쳐 퍼졌다. 산업혁명은 100년, 정보혁명은 30년이었고, AI 혁명은 10년, 어쩌면 그보다 짧을 수 있는데, 기술이 기술을 개발하는 자기 강화 루프가 작동하기 시작했기 때문이다."},{"k":"p","t":"둘째, 범위가 전 영역이다. 이전 혁명들은 특정 산업이나 직군을 주로 바꿨다. 산업혁명은 농민과 장인에게 충격을 주었고, 정보혁명은 사무직을 흔들었다. 그러나 AI 혁명은 의사와 변호사, 작가와 예술가, 교사와 회계사와 프로그래머 — 지식 노동자 전체를 동시에 건드린다."},{"k":"p","t":"셋째, 주체가 뒤집힌다. 이전의 도구는 인간이 명령하면 작동했다. AI는 인간의 의도를 추론하고 스스로 계획을 세우며 자율적으로 실행하는 방향으로 진화하고 있어서, 인간이 도구를 사용하는 것이 아니라 도구가 인간과 협력하는 관계로 넘어간다."},{"k":"h","t":"두려움과 흥분 사이에서"}],"no":38},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"제5의 물결 앞에서 인간은 두 극단 사이를 오간다. 모든 것이 대체될 것이라는 공포. 모든 문제가 해결될 것이라는 낙관. 둘 다 위험하다. 공포에 사로잡히면 아무것도 배우지 않는다. 낙관에 취하면 아무것도 준비하지 않는다."},{"k":"p","t":"우리에게 필요한 것은 정확한 눈이다. 무엇이 변하고 무엇이 변하지 않는지, 어디서 위협이 오고 어디서 기회가 오는지 읽는 눈. 이 책의 여정은 그 눈을 키우는 과정이다."},{"k":"note","t":"※ 세계경제포럼(WEF)의 「Future of Jobs Report 2025」는 2030년까지 약 1억 7,000만 개의 새로운 일자리가 생기고 약 9,200만 개가 대체·감소해, 순증가 약 7,800만 개가 될 것으로 전망한다. 숫자보다 더 눈여겨볼 대목은 이동의 마찰과 재교육의 속도다."},{"k":"h","t":"토플러의 ‘제3의 물결’과 이 책의 ‘제5의 물결’은 무엇이 같고 다른가"},{"k":"p","t":"앨빈 토플러는 1980년 『제3의 물결』에서 농업·산업·정보 세 단계로 문명을 나누었다. 우리가 말하는 ‘제5의 물결’은 그 위에 두 개의 파도를 더 얹는다."},{"k":"p","t":"토플러는 정보혁명까지를 ‘근대 문명의 연장선’으로 보았지만, 플랫폼혁명과 AI 혁명은 그 연장선 바깥에 있는데, 이것은 도구의 진화가 아니라 ‘누가 판단하는가’라는 주체가 바뀌는 사건이기 때문이다. 토플러가 살아 돌아왔다면 어땠을까. 분명 이렇게 말했을 것이다."},{"k":"quote","t":"「제3의 물결은 정보의 흐름을 바꿨다. 제5의 물결은 판단의 주체를 바꾼다. 후자가 더 크다.」"},{"k":"h","t":"북유럽이 먼저 연 문 — 핀란드 ‘엘리먼츠 오브 AI’ 캠페인"},{"k":"p","t":"핀란드는 2018년 한 가지를 결심했다. 자국 인구의 1%에게 AI를 가르치자. 그 후 목표는 다시 커졌다. 인구의 1%에서 EU 인구의 1%로."}],"no":39},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"방법은 단순했다. 무료 온라인 강좌 ‘엘리먼츠 오브 AI’를 만들고, 영어 외 22개 언어로 옮겨 누구나 들을 수 있게 했다. 결과는 놀라웠다. 2024년까지 전 세계 170개국에서 100만 명 이상이 수강했다."},{"k":"p","t":"핀란드는 AI 강대국이 아니다. 그러나 시민 AI 리터러시에서는 단연 강국이 되었다. 교훈은 짧다. 기술 수입국도 시민 교육에서는 얼마든지 앞설 수 있다. 북유럽의 작은 나라가 강좌 하나를 여러 언어로 옮겨 심는 동안 우리가 미뤄 둔 것은 예산도 기술도 아니었고, 누구든 걸어 들어올 수 있는 문 하나를 먼저 열어 두겠다는 결심이었다."},{"k":"note","t":"※ Elements of AI는 EU의 디지털 교육 정책 모범 사례로 자주 인용된다(EU 디지털 교육 행동계획, 2021)."},{"k":"h","t":"인프라는 있는데 학습이 없다"},{"k":"p","t":"한국은 디지털 인프라가 상당히 높은 수준이다. 그런데 인프라가 학습으로 저절로 전환되지는 않는다. 세 가지 입구가 필요하다."},{"k":"p","t":"먼저, 직장 단위 입구다. 모든 회사가 분기에 한 번 ‘AI 사용 회고’ 시간을 갖는다. 어떤 업무에서 효과를 봤고 어디서 실수했는지 나눈다. 그다음, 학교 단위 입구다. 학생이 AI를 쓰는 것을 막을 수는 없다. 대신 ‘AI와 함께 푼 과정’을 평가 항목에 넣는다. 세 번째, 지역 단위 입구다. 도서관과 행정복지센터, 노인복지관과 청년센터에 AI 무료 강좌를 의무로 둔다. 입구가 곳곳에 있어야 그 누구도 뒤처지지 않는다."},{"k":"h","t":"매일 아침 5분, 파도를 읽어 주는 편지"},{"k":"p","t":"매일 변하는 AI 흐름을 따라잡기는 어렵다. 그러나 5분만 들여 ‘오늘 한국 직장인에게 의미 있는 변화 한 가지’만 짚어주는 뉴스레터라면 실행 가능한 수요가 있다."}],"no":40},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"차별점은 세 갈래로 선명하다. 먼저, 영어 기사 번역이 아니라 한국형 의미 해석. 그다음, 정보 나열이 아니라 한 가지 실행 미션. 세 번째, 5분이라는 약속을 절대 깨지 않는 분량."},{"k":"p","t":"이 모델은 글로벌에서도 이미 검증됐다. 영어권 AI 뉴스레터 가운데 The Neuron, 그리고 Superhuman은 각각 100만 명이 넘는 구독자를 모았다. 한국어판 시장은 아직 빈자리가 크다."},{"k":"h","t":"빠른 사람보다 오래 묻는 사람"},{"k":"p","t":"교육장 뒤편에 오래 남은 말 — 기업 교육 현장에서 느낀 것은 하나다. 빠른 사람보다 오래 묻는 사람이 결국 더 정확한 결정을 내린다."},{"k":"p","t":"회의실. 입사 6개월 차 신입사원이 노트북을 연다. 선배가 의뢰한 경쟁사 분석을 10분 만에 끝낸다. 표는 깔끔하고 그래프는 정돈됐다. 선배는 잠시 놀란다. 자신이 사흘 걸리던 작업이다."},{"k":"p","t":"그러나 회의가 끝난 뒤 선배는 다시 생각한다. 신입은 빨랐지만 깊지 않았다. 표에는 없는 ‘시장의 분위기’를 그는 짚지 못했다. 작년에 그 회사가 어떤 인물을 영입했고, 그 인물이 어떤 전략을 선호하는지를."},{"k":"p","t":"이 회의실의 진짜 메시지는 단순하다. 누가 더 빠르냐는 이제 흥미로운 질문이 아니다. 누가 더 좋은 판단을 하느냐가 새로운 경쟁의 무게중심이다. 십 분 만에 뽑아낸 표와 사흘을 들여 쌓은 감각이 같은 회의 탁자에 놓였을 때, 결국 사람들이 오래 들여다본 쪽은 빠른 표가 아니라 그 표가 미처 담지 못한 여백이었다."},{"k":"p","t":"3분이면 그려지는 내 산업의 변화 지형"},{"k":"p","t":"당신이 속한 산업이나 직업의 변화를 좌표로 그려 보자. 가로축은 AI가 이미 변화시킨 영역(왼쪽)에서 아직 변화시키지 못한 영역(오른쪽)으로. 세로축은 변화 속도가 빠른 항목(위)에서 느린 항목(아래)으로. 각 사분면에 당신 업의 구체적인 일들을 적어 보라."}],"no":41},{"part":"제1부 2장","title":"제5의 물결, 무엇이 다른가","sid":"s13","blocks":[{"k":"p","t":"좌상단은 이미 변했고 더 빠르게 변하는 일이다. 지금 익혀야 할 영역이다. 우상단은 아직 변하지 않았지만 곧 빠르게 변할 일이다. 다음 1년의 학습 우선순위다. 좌하단은 이미 변했지만 안정기에 든 일이다. 기본기로 다질 영역이다. 우하단은 변화가 느린 일이다. 인간 가치가 가장 오래 남을 영역이다."},{"k":"p","t":"좌표가 채워지면 다음 한 해의 학습 계획이 자연스럽게 보인다."},{"k":"h","t":"이번 주, 내 산업의 좌표를 직접 찍는다"},{"k":"p","t":"이번 주 가장 오래 걸린 일 하나를 고른 뒤, 준비·판단·전달 단계로 쪼개라. 그중 AI가 도울 수 있는 단계와 사람이 책임져야 할 단계를 서로 다른 색으로 표시해 보라."},{"k":"p","t":"그리고 오늘 당신이 속한 조직에서 통용되는 ‘당연한 규칙’ 세 가지를 적은 다음, 그 세 가지를 AI에게 보여주고 “이 규칙이 5년 뒤에도 유효할까?”라고 물어 보라. AI의 답이 맞느냐는 상관없다. 그 질문을 자신에게 던졌다는 사실이 이미 시작이다."},{"k":"h","t":"다섯 번째 파도가 남기고 간 말"},{"k":"p","t":"이번 물결은 손의 속도가 아니라 생각의 속도를 바꾼다. 변하는 것은 일의 양이 아니라 일의 무게중심이다. 무게중심은 이미 옮겨 갔다. 남은 질문은 어떤 도구를 살 것인가가 아니라, 회의실 불이 꺼진 뒤 마지막 한 줄을 자기 이름으로 남기는 사람이 이 문명에 몇이나 남아 있는가다."},{"k":"quote","t":"「제3의 물결이 정보의 흐름을 바꿨다면, 제5의 물결은 판단의 주체를 바꾼다.」"}],"no":42},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"3장"},{"k":"h","t":"인류의 마지막 문명인가,\n새로운 시작인가"},{"k":"p","t":"불안이 올라오면 지우려 하지 말고 출처를 적어 보라. 그 불안은 기술을 모른다는 부끄러움이 아니라 문명이 방향을 잃을 수 있다는 감각에서 오는데, 마지막 문명이 될지 새로운 시작이 될지는 그 감각을 어떻게 읽느냐에 달려 있다. 오늘의 불안을 한 줄로 적어 보라. 문장은 짧아도 좋다. 때로 가장 솔직한 불안이 가장 빠른 전략의 입구가 된다."},{"k":"h","t":"두 개의 시나리오, 두 개의 진영"},{"k":"p","t":"AI 전문가들의 세계에는 두 개의 진영이 있다. 하나는 실존적 위협론자들이다. 일론 머스크는 AI를 “인류 문명의 가장 큰 위험”이라 불렀다. AI 안전 연구자 엘리저 유드코프스키는 지금의 AI 개발 경쟁이 인류 멸종으로 이어질 수 있다고 경고한다. 2023년 ‘AI 일시 중단 공개서한’에는 수천 명의 연구자와 기업가가 서명했다."},{"k":"p","t":"다른 진영은 가속주의자들이다. 구글 딥마인드 공동창립자 데미스 하사비스는 AI가 암과 노화를 정복할 것이라고 말하고, 미래학자 레이 커즈와일은 2045년 특이점이 온다고, 그 시점에 AI의 지능이 인류 전체의 지능을 합한 것보다 커진다고 예측한다."},{"k":"p","t":"어느 쪽이 옳은가. 아마 둘 다 일부분씩 옳고 틀렸을 것이다. 그런데 이 극단적인 논쟁에서 정작 빠진 것이 있다. 지금 살아가는 보통 인간의 이야기다."},{"k":"h","t":"역사가 증언하는 것 — 러다이트의 교훈"},{"k":"p","t":"우리는 이미 비슷한 공포를 겪었다. 1820년대 영국. 방직 노동자들이 자기 일을 빼앗아가는 기계를 부쉈다. 러다이트 운동이다. 그들의 공포는 현실이었다. 실제로 수십만 명의 방직 일자리가 사라졌다."}],"no":43},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"그런데 100년 후를 보면 그 기계들은 더 많은 일자리를 만들었는데, 공장 노동자와 기차 기관사, 전신 기사와 유통 인력까지 산업화가 만든 직업은 사라진 것보다 훨씬 많았다. 평균 수명은 늘었다. 굶주림은 줄었고, 교육 기회가 넓어졌다."},{"k":"p","t":"AI도 같은 패턴을 따를까. 조심스럽게 말해야 한다. 이번 물결이 이전과 다른 점이 있기 때문이다. 이전의 기계는 육체적 반복 작업을 대체했다. AI는 인지적·창의적 작업을 대체한다. 적응에 더 오랜 시간과 더 깊은 재교육이 필요하다는 뜻이다. 100년 전의 방직공이 1년의 훈련으로 공장 노동자가 될 수 있었다면, 오늘의 사무직은 1년의 훈련으로 무엇이 될 수 있는가. 이 질문에 사회는 아직 답을 갖고 있지 않다."},{"k":"p","t":"인류의 미래를 결정짓는 시나리오는 단순하다. AI가 인류의 마지막 문명이 되는 비극은 요란한 폭발음과 함께 오지 않고, 지극히 고요하고 무력한 방식으로 인간이 스스로 ‘방향 감각’을 잃을 때 완성된다. 속도에 눈이 멀어 어디로 가는지, 왜 가는지 묻지 않는 삶. 사유와 결정의 모든 단계를 알고리즘에 기꺼이 외주화하고, 그 편리함의 대가로 책임의 무게를 지워버리는 것."},{"k":"p","t":"아무도 결과에 책임지지 않는 세상. 문명의 종말은 이토록 정교하고 세련된 모습으로 찾아온다. 그러나 AI가 인류의 새로운 새벽이 되는 시나리오 역시 단 하나뿐인데, 인간이 기술의 속도보다 단 한 발짝 먼저 원칙의 자리를 선점하는 것이다."},{"k":"p","t":"무엇을 위해 이 거대한 힘을 사용하는가. 이 풍요의 파도 속에서 누가 혜택을 받고 누가 소외되는가. 우리가 먼저 지켜야 할 가치는 기술의 골격 어디에 내장되어야 하는가. 이 질문을 던지는 자들만이 기술의 독주를 막아서는 브레이크가 된다."}],"no":44},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"이 책이 그 모든 혼란에 하나의 정답을 내려주겠노라 감히 약속하지는 않겠다. 오만한 확신만큼 시대를 망치는 것은 없기 때문이다. 다만 이것만큼은 확언할 수 있는데, 정답을 갈구하는 자가 아니라, 집요하게 질문하는 인간이 많아질수록 이 문명은 마침표가 아닌 완전히 새로운 시작의 서막을 열게 될 것이다. 확신을 파는 쪽은 마이크를 잡고, 질문을 품은 쪽은 대개 맨 뒷줄에 앉는다. 그런데 회의가 끝난 뒤 배의 키를 끝까지 놓지 않고 있던 손은 늘 그 뒷줄에서 올라왔다."},{"k":"h","t":"해외 정책 현장에서 본 신호 — 영국 AI 안전 연구소"},{"k":"p","t":"영국은 2023년 세계 최초로 ‘AI 안전 연구소’를 세웠다. 목적은 단순하다. 가장 강력한 AI 모델이 출시되기 전, 정부가 그 위험을 미리 평가할 권한과 능력을 갖는 것."},{"k":"p","t":"이 연구소는 오픈AI와 앤트로픽, 구글 딥마인드의 최신 모델을 출시 전에 시험한다. 사이버 보안 위험, 생물학적 위험, 자율성 위험을 점검한다. 미국과 일본, 한국과 EU가 비슷한 기관 설립을 뒤따랐다."},{"k":"p","t":"여기서 남는 답은 하나로 좁혀진다. 기술 개발 속도를 늦추지 않으면서 안전을 점검하는 방법은, 존재한다."},{"k":"note","t":"※ 영국 AI 안전 연구소는 2025년 2월 14일 명칭을 AI Security Institute로 바꿨다(영국 과학혁신기술부 발표). 설립 당시의 원어는 AI Safety Institute다. ‘Bletchley Declaration’(2023년 11월 1~2일)의 후속 조치이며, 28개국과 유럽연합(EU)이 서명했다."},{"k":"h","t":"한국형 실행 전략 — 고래들의 전장에서 살아남기"}],"no":45},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"거대 언어 모델을 두고 벌어지는 미국과 중국, EU의 패권 경쟁 속에서 한국이 그들과 똑같은 규칙으로 싸워 이기기란 불가능에 가깝다. 냉정하게 말해 체급이 다르다. 그렇다면 이 거대한 판을 떠나야 할까. 아니다. 판을 바꾸면 된다. 최강자가 될 수 없다면, 대체 불가능한 ‘믿을 만한 중간자’가 되는 길을 택하는 것이다."},{"k":"p","t":"한국이 가진 드문 강점은 높은 밀도의 인구가 만들어내는 경이로운 속도와 응집력이다. AI 응용, AI 안전 평가, AI 윤리 거버넌스, 그리고 AI K-콘텐츠. 이 네 가지 전장은 막대한 자본력보다 기민한 협업과 빠른 실행력이 승패를 가르는 곳이며, 동시에 한국이 가장 잘할 수 있는 영역이다."},{"k":"p","t":"특히 ‘AI 안전 평가’는 앞으로 글로벌 시장을 뒤흔들 신뢰의 비즈니스다. 우리가 설계한 정교한 가이드라인과 ‘K-AI 안전 인증’이 동남아와 중동과 아프리카로 수출될 때, 한국은 기술 패권의 종속국이 아니라 모두가 신뢰하는 중재자로 우뚝 서게 된다."},{"k":"h","t":"두려움을 매출로 바꾸는 사람들"},{"k":"p","t":"거대한 판이 갈리는 일기에는 언제나 짙은 그늘이 서린다. 지금 우리 사회를 지배하는 정서는 하나다. 단연 ‘두려움’이다. 학부모와 교사, 골목길의 자영업자, 은퇴를 앞둔 중장년 직장인까지 모두가 AI라는 거센 물결 앞에서 길을 잃었는데, 시장은 이 불안을 끊임없이 자극할 뿐 누구도 실질적인 나침반을 쥐여주지 않는다."},{"k":"p","t":"여기에 거대한 비즈니스의 기회가 숨어 있다. 두려움을 부정하는 대신, 그것을 성장의 출발점으로 삼는 정교한 마이크로 컨설팅이다. 구체적 모델 세 개를 들어 보자."}],"no":46},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"하나. 부모 전용 ‘1시간 AI 코칭’ 컨설팅. 우리 아이가 미래에 어떤 직업을 가져야 안전할지 점치는 대신, AI 시대에 결코 대체되지 않을 인간 고유의 ‘역량’을 어떻게 설계할 것인지 밀착 코칭한다. 직업의 소멸에 떨지 않고 역량의 확장에 집중하게 만드는 1:1 상담이다."},{"k":"p","t":"둘. 자영업자 ‘30분 매장 AI 진단’ 컨설팅. 우리 매장에서 무의미하게 반복되는 업무 세 가지를 정확히 골라내고, 당장 내일부터 적용할 수 있는 가장 작은 AI 실험 한 가지를 처방한다. 골목상권이 기술을 무기로 쥐는 순간이다."},{"k":"p","t":"셋. 중장년 재취업 ‘AI 친화 공존형 이력서 재설계’ 컨설팅. 기술에 밀려날 노동자가 아니라, AI를 도구로 부릴 줄 아는 ‘숙련된 관리자’로서의 경험을 증명하고 ‘AI와 함께 일하는 역량’을 강조한 이력서로 재설계하는 패키지다."},{"k":"p","t":"세 모델에는 공통된 결이 있다. 두려움을 피하지 않고, 오히려 변화를 시작할 가장 확실한 연료로 삼는다는 것. 시대를 이끄는 것은 대단한 기술 그 자체가 아니라, 인간의 불안을 읽어내고 그것을 행동으로 전환하는 공감의 힘이다. 상담 한 시간이 끝날 무렵 사람들이 지갑을 여는 이유는 대단한 기술 정보를 얻어서가 아니라, 아무에게도 말하지 못하던 자기 두려움이 처음으로 다룰 만한 크기로 줄어드는 것을 눈앞에서 보았기 때문이다."},{"k":"h","t":"식탁 위에서 시작된 질문 — 인간의 자리를 묻다"},{"k":"p","t":"상담실 문을 닫고 적은 메모 — 학부모 상담 자리에서는 기술 이야기보다 아이의 마음 이야기가 먼저 나온다. AI 시대의 교육은 그래서 직업표보다 인간표를 먼저 그려야 한다."},{"k":"p","t":"초등학교 4학년 아이가 저녁 식탁에서 묻는다."},{"k":"quote","t":"“엄마, AI가 나보다 훨씬 똑똑한데 난 왜 공부해야 해?”"},{"k":"p","t":"엄마는 잠시 말이 막힌다. 그녀 자신도 같은 질문 앞에서 흔들리고 있다. 그녀는 즉답하지 않는다. 대신 다른 질문을 꺼낸다."}],"no":47},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"quote","t":"“AI는 네가 슬플 때 같이 슬퍼해줄까? 네 친구가 다쳤을 때 누가 곁에 있어줘야 할까?”"},{"k":"p","t":"아이는 생각한다. 한참 생각한다. 그리고 다시 묻는다."},{"k":"quote","t":"“그럼 나는 마음을 잘 쓰는 사람이 되면 돼?”"},{"k":"p","t":"엄마는 그제야 답한다. 그것도 한 가지 답이고 정답은 아직 정해지지 않았으니, 다만 묻는 일만은 끝까지 놓지 말라고. 평범한 저녁 식탁이 순식간에 거대한 미래의 문턱으로 변하는데, 그 문을 열어젖히는 손길은 눈부신 기술이 아니라 오직 인간만이 던질 수 있는 집요한 질문이다. 그날 식탁에서 엄마가 아이에게 준 것은 정답이 아니라 되묻는 법이었고, 훗날 그 아이를 지켜 줄 것도 외워 둔 지식이 아니라 그날 저녁에 배운 그 한 번의 되물음일 것이다."},{"k":"h","t":"두려움을 해부대 위에 올려 보자"},{"k":"p","t":"두려움이 지닌 가장 큰 무기는 ‘막연함’이다. 실체를 알 수 없는 안개 속에서 공포는 무한히 증식한다. 그러나 그것을 활자로 받아 적는 순간, 실체 없던 괴물은 통제 가능한 숫자가 되고 다룰 수 있는 매뉴얼이 된다. 글로 쓰면 작아진다. 불안을 무기로 바꾸는 5단계 해부법이다."},{"k":"p","t":"[1단계] AI에 대해 당신이 가진 가장 큰 두려움을 단 한 문장으로 적어라. [2단계] 그 두려움이 실제로 당신의 삶에 닥칠 확률을 냉정하게 수치화하라. 1점부터 10점까지. [3단계] 그 두려움이 5년 뒤 현실이 된다면, 어떤 신호가 먼저 보일까. 신호 세 가지를 적어라. [4단계] 그 신호가 보이기 전에, 당신이 지금 할 수 있는 작은 준비 한 가지는 무엇인가. [5단계] 그 준비를 이번 주에 시작할 첫 번째 행동으로 바꿔라."},{"k":"p","t":"두려움이 행동으로 옮겨가는 순간, 두려움은 자기 동력이 된다. 막연한 불안이 아니라 구체적인 준비가 된다."},{"k":"h","t":"독자 실행 과제 — 타인의 유령을 받아 적다"}],"no":48},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"한 주 동안 AI를 가장 두려워하는 사람을 한 명 만나서 30분 동안 그의 두려움을 듣고 받아 적어라. 조언도, 처방도, 섣부른 위로도 필요 없다. 어떠한 판단도 배제한 채 오직 침묵으로 경청하라."},{"k":"p","t":"신기하게도 그 배낭을 나누어 매는 순간, 당신을 짓누르던 두려움의 무게 역시 한 꺼풀 가벼워짐을 느낄 것이다. 기계가 결코 흉내 낼 수 없는 인간의 마지막 고유 자산. 그것은 또 다른 인간이 품은 깊은 두려움의 파동을 함께 견뎌내는 경청의 능력이다."},{"k":"h","t":"블레츨리 선언과 그 이후 — 인류가 그어야 할 선"},{"k":"p","t":"2023년 가을, 영국 블레츨리 파크의 문이 열렸을 때 세계는 묘한 긴장감에 휩싸였다. 2차 세계대전 당시 천재 수학자들이 모여 독일군의 암호 ‘에니그마’를 해독했던 그 역사적 장소에, 이제는 인공지능이라는 인류 최후의 암호를 풀기 위해 세계의 머리들이 다시 모인 것이다."},{"k":"p","t":"28개국과 EU가 뜻을 모은 ‘블레츨리 선언’은 인공지능이라는 통제 불능의 전차에 인류가 처음으로 공식적인 제동장치를 달기로 합의한 순간이었다. 그날 이후, AI 거버넌스의 시계바늘은 유례없이 빠르게 돌기 시작했다."},{"k":"p","t":"2023년 11월 영국 블레츨리 파크. 선언의 결은 분명했다. 초거대 AI가 가져올 통제 불가능한 위험을 인류가 공동으로 관리해야 한다는 최초의 다자간 합의였다. 2024년 5월 대한민국 서울. 바통을 이어받은 ‘서울 AI 정상회의’에서는 글로벌 거대 기술 기업 16곳이 ‘프런티어 AI 안전 약속’에 서명했다. 국가의 선언이 기업의 실천적 구속력으로 진화하는 변곡점이었다."}],"no":49},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"2024년 가을 미국과 EU. 기술을 검증할 차가운 메스가 준비됐다. 두 곳의 ‘AI 안전성 연구소(AISI)’가 본격 가동되며, 알고리즘의 심장부를 들여다볼 합동 평가 프레임워크가 세워졌다. 2025년 프랑스 파리. ‘AI 액션 서밋’을 거치며 논의의 기류가 바뀌었다. 초점은 ‘안전’이라는 방어적 태도에만 머물지 않고, 기술을 어떻게 공공의 자산으로 환원할 것인가라는 ‘공공 이익’의 영역으로 넓어졌다. 2026년 초 유엔. 인류 역사상 가장 거대한 제도적 사원이라 할 만한 유엔 차원의 ‘글로벌 AI 거버넌스 기구’ 출범 논의가 본격화되고 있다."},{"k":"p","t":"이 흐름의 본질은 무엇인가. 짚어야 할 것은 두 가지다."},{"k":"p","t":"첫째는 ‘프런티어 모델(Frontier Model)’에 대한 사전 통제다. 인류가 아직 가보지 못한 미지의 영역에 있는 최첨단 초거대 AI에 대해서는, 시장에 나오기 전 국가적 차원의 검증과 평가를 의무화하겠다는 합의가 모이고 있다. 기술이 인간의 통제력을 앞서 나가게 두지 않겠다는 결연한 방어선이다."},{"k":"p","t":"둘째는 ‘공공 이익(Public Interest)’이라는 새 키워드의 등장이다. 어둠을 막아내는 것만큼이나 빛을 밝히는 것이 중요해졌기 때문이다. AI의 공포를 통제하는 단계는 지났다. 이제 의제는 다른 쪽으로 옮겨 갔다. 교육과 의료와 노동과 기후변화 같은 인류 공동의 난제를 풀기 위해, 이 거대한 힘을 어떻게 올바르게 동원할 것인가."},{"k":"p","t":"2023년 인류는 ‘AI가 위험할 수 있다’는 공포에 합의했고, 2026년 우리는 ‘AI를 어떻게 인류의 동맹으로 만들 것인가’라는 실존적 질문에 답을 모아야 할 차례다. 그 사이 3년. 인류의 방향타를 쥔 가장 결정적인 순간이었다."},{"k":"h","t":"두려움과 기대 사이, 어디에 발을 딛을까"}],"no":50},{"part":"제1부 3장","title":"인류의 마지막 문명인가, 새로운 시작인가","sid":"s14","blocks":[{"k":"p","t":"위험을 부정하는 낙관도, 가능성을 닫는 공포도 인간을 구하지 못하고, 우리를 구하는 것은 오직 하나, 파도처럼 밀려오는 기술의 본질을 응시하며 묻기를 멈추지 않는 인간의 연대다. 앞으로의 5년 한복판에서 챙겨야 할 것은 더 빠른 답이 아니라, 회의실 사람들이 모두 고개를 끄덕일 때 혼자 손을 들어 한 번 더 되묻는 쪽에 서는 일이다."},{"k":"quote","t":"「인류의 마지막 문명이 될 것인가, 아니면 완전히 새로운 시작이 될 것인가. 그 거대한 주사위는 지금, 우리가 관통하고 있는 이 5년의 시간 속에 던져져 있다.」"}],"no":51},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"4장"},{"k":"h","t":"질문하는 인간의 귀환"},{"k":"p","t":"우리는 오랫동안 답을 가진 사람을 뛰어난 사람이라 믿어왔다. 남보다 빨리 맞히는 사람, 더 많이 아는 사람, 틀리지 않는 사람이 인재였고, 학교는 그런 사람에게 높은 점수를 주었으며, 조직은 그런 사람에게 더 큰 자리를 내주었다."},{"k":"p","t":"그러나 어느 순간부터 세상의 규칙이 조용히 바뀌기 시작했다. 이제 답은 인간만의 능력이 아니다. 몇 시간을 고민하던 문제를 AI는 몇 초 만에 정리하고, 누군가 평생 쌓은 지식의 조각들도 순식간에 엮어 내는데, 예전 같으면 ‘대단하다’고 불렸을 그런 답이 이제는 너무 쉽게, 너무 빠르게, 너무 많이 쏟아진다."},{"k":"p","t":"그래서 이상한 일이 벌어졌다. 답이 넘쳐나는 시대가 되었는데, 사람들은 오히려 더 자주 길을 잃는다. 왜일까. 답이 부족해서가 아니다. 무엇을 물어야 하는지 잊었기 때문이다."},{"k":"p","t":"좋은 질문은 멋진 문장을 만들기 위한 장식이 아니다. 그것은 닫혀 있던 문제의 문을 다시 여는 손잡이이고, 굳어버린 생각에 금을 내고, 당연하다고 믿었던 선택지를 흔들며, 결국 다음 행동의 방향을 바꾸는 작은 지휘봉이다."},{"k":"p","t":"AI가 강해질수록 인간에게 더 절실해지는 능력은 빠르게 대답하는 힘이 아니다. 더 깊이 묻는 힘이다. 누구나 같은 도구를 손에 쥐는 시대에는 도구 자체보다 그것을 깨우는 질문의 수준이 사람의 차이를 만든다. 어떤 질문은 평범한 답을 끌어낸다. 어떤 질문은 그럴듯한 문장을 만든다. 아주 드물게, 어떤 질문은 삶의 방향을 바꾼다."},{"k":"p","t":"사람들은 이것을 프롬프트 엔지니어링이라고 부른다. 하지만 조금만 벗겨보면, 그 안에 있는 것은 낯선 기술이 아니다. 결국 질문하는 힘이다. 우리는 오래전부터 질문으로 세상을 바꿔왔다."},{"k":"quote","t":"“왜 이래야 하지?” “다른 방법은 없을까?” “정말 이게 최선일까?”"}],"no":52},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"모든 변화는 이런 작은 질문에서 시작됐다. 누군가는 당연한 것을 그냥 넘기지 않았고, 모두가 고개를 끄덕일 때 혼자 조용히 다른 가능성을 물었으며, 그 질문 하나가 길을 만들었다. 일의 방식을 바꾸었다. 때로는 한 사람의 인생까지 바꾸었다."},{"k":"p","t":"AI는 이제 답을 잘한다. 그것도 아주 빠르게 잘해서, 우리가 몇 시간 동안 붙잡고 있던 자료를 순식간에 정리하고, 막막하던 문장을 그럴듯하게 풀어내며, 복잡한 아이디어까지 보기 좋게 배열해준다. 그런데 여기서 남는 문제가 있다. AI가 답을 줄 수는 있지만, 어떤 답을 구해야 하는지는 스스로 정하지 못한다."},{"k":"p","t":"무엇을 물을 것인가. 어디까지 맡길 것인가. 그 답을 어떤 기준으로 받아들일 것인가. 그리고 그 답이 정말 사람과 세상을 더 나은 방향으로 움직이게 하는가."},{"k":"p","t":"이 질문들은 여전히 인간의 몫이다. 앞으로 더 귀해지는 사람은 AI를 무작정 잘 쓰는 사람이 아니라, AI에게 방향을 주고, 기준을 세우고, 결과를 다시 해석할 줄 아는 사람이다. 말하자면 AI를 지휘하는 사람, 바로 ‘AI 디렉터’다."},{"k":"p","t":"AI 디렉터는 명령어를 잘 쓰는 사람이 아니라, 문제의 핵심을 보고, 질문의 방향을 잡고, AI가 꺼내놓은 답 속에서 진짜 쓸모 있는 것을 골라내는 사람이다. 이제 우리는 다시 배워야 한다. 더 많이 아는 법이 아니라 더 깊이 묻는 법을. 더 빨리 대답하는 법이 아니라 잠시 멈춰 본질을 보는 법을."},{"k":"p","t":"앞으로의 시대는 답을 많이 가진 사람보다, 좋은 질문을 끝까지 붙잡는 사람에게 더 많은 기회를 준다. AI가 답을 만드는 시대일수록, 인간은 질문으로 자신의 자리를 되찾아야 한다."},{"k":"h","t":"질문의 세 가지 층위"}],"no":53},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"소크라테스는 질문으로 철학을 했다. 그의 질문은 세 가지 층위를 가졌다. 사실 확인 — 이것이 정말 그런가. 가정 도전 — 이것이 항상 그런 것인가. 목적 탐구 — 이것이 좋은 것인가."},{"k":"p","t":"AI 시대에도 이 세 질문의 무게는 오히려 늘어난다. AI가 만들어낸 정보가 사실인지 확인하는 질문. AI의 출력물이 전제하는 가정이 타당한지 묻는 질문. 그리고 AI가 제시하는 방향이 인간에게 좋은 것인지 묻는 질문."},{"k":"p","t":"이 세 질문을 잃어버린 사람은 AI에게 끌려다닌다. 이 질문을 가진 사람은 AI를 이끈다. 차이는 여기에 있다. 수천 년 전 한 철학자는 답을 나눠 주는 대신 상대에게 계속 되물었다. 화면 앞에 앉은 우리가 다시 배워야 할 것도 새 명령어가 아니라 그 되묻는 자세 하나다."},{"k":"h","t":"좋은 질문의 다섯 가지 조건"},{"k":"p","t":"좋은 질문은 그냥 만들어지지 않는다. 다섯 가지 조건이 한 질문 안에 담겨야 한다. 목적 — 이 질문은 무엇을 얻으려고 던지는가. 조건 — 어떤 상황과 제약 아래의 답을 원하는가. 청자 — 누구를 향한 답이어야 하는가. 판단 기준 — 답의 좋고 나쁨을 어떻게 평가할 것인가. 실패 가능성 — 답이 틀렸을 때 어떤 위험이 생기는가."},{"k":"p","t":"이 다섯 가지를 빠짐없이 담은 질문이 AI를 가장 깊이 움직인다. 그리고 다섯 가지를 묻는 사람은 이미 답의 절반을 알고 있는 사람이다."},{"k":"h","t":"답이 아니라 질문에 점수를 준 대학"},{"k":"p","t":"미네르바 대학은 캠퍼스가 없는 글로벌 대학으로, 4년 동안 학생들은 일곱 개 도시를 옮겨 다니며 살고, 이 대학의 가장 큰 특징은 평가 방식에 있다. 학생은 시험에서 정답을 맞히는 것보다 ‘좋은 질문을 만드는 능력’으로 평가된다."}],"no":54},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"수업의 절반은 학생이 자기 질문을 다른 학생들과 함께 검증하는 시간이다. 처음에는 모호하던 질문도 일곱 번의 토론을 거치면 날카로워지고, 그렇게 다듬은 질문을 들고 나간 졸업생들의 취업률과 창업 성공률은 동급 대학을 압도한다. 이유는 단순하다. AI 시대에 가장 비싼 인재는 좋은 질문을 만들어주는 인재다. 그 학교에는 캠퍼스도 강의실 벽도 없었다. 끝까지 남은 것은 도시를 옮겨 다닌 이력이 아니라, 서툰 질문 하나를 여럿 앞에 꺼내 놓고 밤새 같이 깎아 본 시간이었다."},{"k":"note","t":"※ 미네르바 대학(Minerva University)은 2014년 개교 이래 극도로 낮은 합격률을 유지해 왔다. 미국 교육부 IPEDS 집계 기준 2024년 가을 학기 지원자는 10,864명, 합격률은 3%였다(NCES College Navigator, UnitID 484844)."},{"k":"p","t":"빠른 답은 잘 가르치는 나라, 좋은 질문은?"},{"k":"p","t":"한국의 교육은 빠른 답을 잘 가르친다. 그러나 좋은 질문을 잘 가르치지는 못한다. 세 가지 전환이 필요하다."},{"k":"p","t":"우선, 시험에 ‘질문 평가’ 영역을 도입한다. 학생이 직접 만든 질문 세 개를 답안과 함께 내게 한다. 질문의 깊이도 점수가 된다. 이어서, 회사 면접에 ‘질문 단계’를 더해, 지원자에게 답을 묻기 전에 “이 회사의 가장 큰 문제는 무엇인가?”를 먼저 묻게 한다. 좋은 질문을 던지는 지원자가 좋은 일을 한다. 세 번째로, 가정에서 ‘질문 식탁’ 시간을 만들어 주 1회 식탁에서 한 시간 동안 답이 아니라 질문만 주고받되, 부모와 아이가 같은 자리에 앉는다."},{"k":"h","t":"질문 열 개를 카드로 팔 수 있다면"},{"k":"p","t":"좋은 질문은 직업마다 다르다. 의사의 좋은 질문과 디자이너의 좋은 질문은 다르다. 그런데 대부분의 사람은 자기 직업의 ‘핵심 질문 10개’를 정리해 본 적이 없다."}],"no":55},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"여기서 팔 수 있는 물건은 의외로 소박하다. 50개 직업군에 대해 각각 ‘이 직업의 가장 중요한 질문 10개’를 카드로 정리해 판다. 영업직이라면 이런 것들이다. 고객이 진짜로 사고 싶은 것은 무엇인가. 우리 제품의 어떤 부분이 고객의 두려움을 가장 잘 다루는가. 거절의 진짜 이유는 무엇인가."},{"k":"p","t":"이 카드는 신입에게는 학습 도구, 경력자에게는 점검표, 관리자에게는 코칭 자료가 된다. AI에 던질 프롬프트의 출발점으로도 쓰인다. 한 직업군 카드 5천 원, 50개 직업군에 한 명만 사도 25만 원이다. 시장은 작지 않다."},{"k":"h","t":"회의실에서 건져 올린 오후"},{"k":"p","t":"책상 앞 독자에게 건네는 말 — 어느 독자는 “AI가 무섭다기보다, 내가 늦었다는 느낌이 무섭다”고 말했다. 이 책은 바로 그 마음에서 출발한다."},{"k":"p","t":"점심시간이 끝난 회의실. 신입 기획자가 빈 문서 앞에 앉는다. 선배가 “좋은 기획안 좀 써와”라고 던지고 자리를 떴다."},{"k":"p","t":"신입은 처음에 AI에게 그대로 묻는다. “좋은 기획안 써줘.” 결과물은 평범하다. 어디서 본 듯한 구조와 어디서 본 듯한 표현. 신입은 다시 묻는다."},{"k":"quote","t":"“우리 고객의 가장 큰 고통은 무엇인가.” “고객이 그 고통을 줄이기 위해 지금 지불하는 비용은 무엇인가.” “기존 해법은 왜 충분하지 않은가.” “우리가 그것을 풀 수 있는 자원은 무엇인가.” “실패할 가능성은 어디에 있는가.”"},{"k":"p","t":"다섯 개의 질문을 차례로 던진 뒤 그는 AI의 답을 종합해 한 페이지로 다듬고, 저녁에 돌아온 선배가 그 한 페이지를 들여다보다 잠시 침묵하고는 한 문장만 말한다."},{"k":"quote","t":"“네가 쓴 거 아니지?” “제가 묻고 AI가 답한 겁니다.” “묻는 게 네거잖아. 그럼 네가 쓴 거지.”"}],"no":56},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"이 회의실의 침묵이 새로운 시대의 교육이다. 저녁에 돌아온 선배가 던진 그 짧은 한마디는 신입의 실력을 인정한 칭찬이 아니라, 앞으로 무엇이 끝까지 한 사람의 몫으로 남을지를 그 조직이 처음으로 소리 내어 정의한 문장에 더 가까웠다."},{"k":"h","t":"내 직업의 질문 열 개, 오늘은 두 개부터"},{"k":"p","t":"한 번에 열 개를 다 만들 필요는 없다. 다음 다섯 가지 카테고리에서 두 개씩만 시작하라."},{"k":"p","t":"[고객 관점] 우리 고객이 진짜로 원하는 것은 무엇인가. 그들이 말로는 표현하지 못하는 욕구는 무엇인가. [가치 관점] 우리는 어떤 가치를 만드는가. 그 가치를 측정하는 단위는 무엇인가. [경쟁 관점] 경쟁자는 누구인가. 그들이 잘 못하는 것은 무엇인가. [위험 관점] 우리 일이 실패할 가장 큰 가능성은 어디에 있는가. 그것을 미리 알아채는 신호는 무엇인가. [성장 관점] 1년 뒤 우리는 어떤 모습이어야 하는가. 그 모습이 되기 위해 지금 시작할 것은 무엇인가."},{"k":"p","t":"열 개의 질문이 만들어지면, 그것을 매일 한 번씩 자신에게 던져 보라. 일주일 안에 일의 무게중심이 바뀐다."},{"k":"h","t":"한 페이지로 끝내는 워크시트"},{"k":"p","t":"내 업무에서 시간을 빼앗는 10분짜리 반복 행동을 찾아라. 그 행동을 AI에게 맡길 때 필요한 입력값, 검토 기준, 최종 책임자를 각각 한 줄로 정리하라."},{"k":"p","t":"그리고 오늘 하루, 당연하게 여겨 왔던 것들과 늘 그래왔던 것들을 향해 “왜?”라는 질문을 최소 열 번 해 보고, 그 질문들을 적은 뒤 가장 흥미로운 하나를 골라 AI에게 던져 보라. AI의 답이 완전한가? 부족한 부분은 무엇인가? 그 부족함이 당신의 직업이 살아남을 공간이다."},{"k":"h","t":"당신의 질문력은 지금 어디쯤인가 — 5문항 자기진단"},{"k":"p","t":"아래 다섯 문항을 읽고, 각각 1~5점으로 자기 점수를 매겨 보라. 1점은 거의 아니다, 5점은 매우 그렇다."},{"k":"h","t":"총점 해석"}],"no":57},{"part":"제1부 4장","title":"질문하는 인간의 귀환","sid":"s15","blocks":[{"k":"p","t":"20~25점은 질문 마스터다. AI 시대의 리더 그룹이다. 동료들에게 ‘좋은 질문’을 가르치는 자리에 서라. 15~19점은 성장형 질문가다. 의식적 훈련만 더하면 마스터로 도약한다. 이 책의 워크북을 먼저 실행하라."},{"k":"p","t":"10~14점은 답에 의존하는 단계다. 가장 보편적인 상태다. 이 장의 본문과 부록 B로 훈련을 시작하라. 5~9점은 위험 신호다. AI에게 사고를 통째로 위임하는 단계다. 오늘 점심부터 “왜?” 한 번 더 묻기 시작하라."},{"k":"quote","t":"「점수보다 중요한 건 변화의 곡선이다. 6주 후 다시 측정해 보라. 당신이 변하고 있는지, 멈춰 있는지가 보일 것이다.」"},{"k":"h","t":"답은 0.1초, 질문은 평생"},{"k":"p","t":"AI 시대의 권력은 답을 가진 사람이 아니라 질문을 설계하는 사람에게 이동한다. 답은 0.1초의 일이지만, 질문은 평생의 일이다. 평생을 걸어야 하는 일이라는 말이 무겁게 들린다면 순서를 바꿔 생각해도 좋은데, 오늘 하루 던진 질문 하나가 내일의 판단을 조금 낫게 만든다면 그 평생은 이미 시작된 셈이다."},{"k":"quote","t":"「답은 0.1초의 일이다. 질문은 평생의 일이다.」"}],"no":58}];

  /* 연구 아젠다 ↔ 책 챕터 연결 */
